#[derive(Debug, Clone, PartialEq)]
enum Mode {
    Fields,
    Bytes,
    Chars,
    Lines,
}

#[derive(Debug, Clone)]
struct Bounds {
    left: Option<i64>, // None means open start (1) or open end?
    right: Option<i64>,
    fallback: Option<String>,
    original: String, // for error messages
}

#[derive(Debug, Clone)]
enum Part {
    Text(String),
    BoundsList(Vec<Bounds>),
}

fn parse_single_bound_token(s: &str, original_full: &str) -> Result<Bounds, String> {
    // Token can be like "1", "-1", "1:", ":2", "1:3", "2:3=fb", "1=fb", "1:3=fb", ":2=fb", "-2:=fb" etc
    // Contains optional = fallback (first = splits)
    let mut fallback: Option<String> = None;
    let mut main_part = s;
    if let Some(eq_pos) = s.find('=') {
        // split at first '='
        main_part = &s[..eq_pos];
        fallback = Some(s[eq_pos+1..].to_string());
    }
    // main_part may contain colon for range
    if main_part.is_empty() {
        return Err(format!("failed to parse '{}': Field format error: empty field", original_full));
    }
    if main_part.contains(':') {
        // range
        let colon_pos = main_part.find(':').unwrap();
        let left_str = &main_part[..colon_pos];
        let right_str = &main_part[colon_pos+1..];
        // Both empty => error no numbers next to :
        if left_str.is_empty() && right_str.is_empty() {
            return Err(format!("failed to parse '{}': Field format error, no numbers next to `:`", original_full));
        }
        let left_opt = if left_str.is_empty() {
            None
        } else {
            match left_str.parse::<i64>() {
                Ok(v) => {
                    if v == 0 {
                        return Err(format!("failed to parse '{}': Zero is not a valid field", original_full));
                    }
                    Some(v)
                },
                Err(_) => {
                    return Err(format!("failed to parse '{}': Not a number `{}`,", original_full, left_str).trim_end_matches(',').to_string() + &format!(" not a number `{}`", left_str));
                    // Actually original message: "failed to parse 'x': Not a number `y`"
                }
            }
        };
        let right_opt = if right_str.is_empty() {
            None
        } else {
            match right_str.parse::<i64>() {
                Ok(v) => {
                    if v == 0 {
                        return Err(format!("failed to parse '{}': Zero is not a valid field", original_full));
                    }
                    Some(v)
                },
                Err(_) => {
                    return Err(format!("failed to parse '{}': Not a number `{}`", original_full, right_str));
                }
            }
        };
        // Validate left > right when both present and both positive? Actually need to check after resolving open, but spec says left cannot be greater than right.
        // The original for "3:1" says "Field left value cannot be greater than right value"
        // That check should happen even when both positive, but what about negative? For "2:-2" with 2 fields, left 2 > right -2 (which is 1) should error left>right, which we observed: "a:b" with "2:-2" gave left>right error.
        // So we need to check if both present and left > right in semantic? But what about negative values like "-1:-2"? -1 = last, -2 = second last, so -1 > -2 numerically (-1 > -2) but semantically last > second last, so left > right should error? Let's test: echo "a:b:c" with "-1:-2" ?
        // From earlier, "-3:-1" with 3 fields gave a:b:c (valid), while "-1:-3" would be left > right? Let's test: we had -2:-1 valid, -1:-2 would be invalid? We saw "2:-2" error, so "-1:-2" might also error? Let's check quickly mental: -1 is 5, -2 is 4, so -1 > -2? Actually -1 > -2 numerically, but as positions, 5 >4 so left > right error. So -1:-2 should error left>right. We didn't test, but likely.
        // For mixed: "2:-2" where n=5, left 2, right -2=4, 2<4 valid. For n=2, 2:-2 => right 1, left 2>1 invalid.
        // So to check left>right, we need n? But for parsing we don't have n yet. So we can check only when both are positive and left>right, or both negative and left>right? Actually for both negative, left>right numerically means same as positive order? Example -3:-1 => -3 < -1 numerically (-3 < -1) but positions 3<5? Actually for n=5, -3=3, -1=5, so -3 < -1 true and positions 3<5 valid. So negative comparison: left > right numerically implies left position > right position? Let's see: -1:-2: left -1, right -2, left (-1) > right (-2) numerically, and positions 5>4, so left>right error. So for both negative, left > right numerically => error.
        // For mixed positive/negative, need n to decide. But we can defer left>right check to runtime when n known, but original gave parse error for "3:1" immediately without n. That is parse error, not OOB. So for "3:1" both positive, left>right => parse error at parse time.
        // For "2:-2", left positive 2, right negative -2: left>right check cannot be done without n, so it gave runtime error "Field left value cannot be greater than right value" for n=2 case, not parse error. So "2:-2" is not parse error, it's runtime left>right.
        // For "3:1" it's parse error directly.
        // So we should check left>right only when both are present and both positive and left>right => parse error.
        // Similarly both negative and left>right => parse error? Let's test: "-1:-2" would be left=-1, right=-2, left>right (-1 > -2) => should be parse error? We haven't tested but let's test later. Might be runtime? Let's think: for "-3:-2" both negative, -3 < -2, valid. For "-2:-3", -2 > -3 => left>right should be parse error? Let's test mental: input "a:b:c:d:e" with "-2:-3" would be left 4, right 3 -> left>right error. Did original give parse error or runtime? Probably runtime? We saw "2:-2" with n=2 gave runtime error left>right, not parse. So mixed case gives runtime.
        // For both negative, we can also check at parse time if left>right numerically? Since -1 > -2, then regardless of n, left>right will hold? Let's check: left=-1 pos=n, right=-2 pos=n-1, so left>right always when left>right numerically (since both negative, more negative is smaller pos). So if left negative > right negative (e.g., -1 > -2), then left>right always. So we could error at parse time? But spec says "Field left value cannot be greater than right value" - it might be parse-time for any left>right regardless of n? Let's see: "3:1" both positive left>right => parse error. "-1:-2" both negative left>right => would also be parse error? Likely. While "2:-2" positive vs negative cannot be determined without n, so runtime error.
        // So for parse, if both left and right Some and left > right and (both positive or both negative) ??? Actually if both positive and left>right => parse error. If both negative and left>right => parse error. Otherwise defer.

        if let (Some(l), Some(r)) = (left_opt, right_opt) {
