fn parse_bounds_list(s: &str) -> Result<Vec<Bounds>, String> {
    if s.is_empty() {
        return Err(format!("failed to parse '': Field format error: empty field"));
    }
    // Split by comma, but need to detect empty tokens
    let parts: Vec<&str> = s.split(',').collect();
    let mut res = Vec::new();
    for part in parts {
        if part.is_empty() {
            return Err(format!("failed to parse '{}': Field format error: empty field", s));
        }
        let b = parse_single_bound_token(part, s)?;
        res.push(b);
    }
    if res.is_empty() {
        return Err(format!("UserBoundsList must contain at least one UserBounds"));
    }
    Ok(res)
}

// Format string parsing
fn parse_format_string(s: &str) -> Result<Vec<Part>, String> {
    // Detect if s contains { or } not escaped? If it contains no braces, it's not format, but we'll treat as bounds.
    // For format parsing, we need to handle {{ and }} escapes.
    // Also need to detect missing opening/closing braces.
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    let mut parts: Vec<Part> = Vec::new();
    let mut current_text = String::new();
    let mut has_bounds = false;

    while i < chars.len() {
        let c = chars[i];
        if c == '{' {
            if i+1 < chars.len() && chars[i+1] == '{' {
                // escaped {
                current_text.push('{');
                i += 2;
            } else {
                // start placeholder
