fn parse_bounds_list(s: &str) -> Result<Vec<Bounds>, String> {
    if s.is_empty() {
        return Err(format!("failed to parse '': Field format error: empty field"));
    }
    // Split by comma, but need to detect empty tokens
    let parts: Vec<&str> = s.split(',').collect();
    let mut res = Vec::new();
    for part in parts {
        if part.is_empty() {
            return Err(format!("failed to parse '{}': Field format error: empty field", s));
        }
        let b = parse_single_bound_token(part, s)?;
        res.push(b);
    }
    if res.is_empty() {
        return Err(format!("UserBoundsList must contain at least one UserBounds"));
    }
    Ok(res)
}

