        if let Some(pos) = line[search_start..].find(delim) {
            let abs_start = search_start + pos;
            let abs_end = abs_start + delim.len();
            occ.push((abs_start, abs_end));
            search_start = abs_end; // non-overlapping
        } else {
            break;
