        // But we have delims as delim each time, correct.
    } else {
        // greedy/compress: group consecutive
        let mut grouped: Vec<(usize, usize)> = Vec::new(); // run start, run end
        let mut i = 0;
        while i < occ.len() {
            let mut run_start = occ[i].0;
            let mut run_end = occ[i].1;
            let mut j = i+1;
            while j < occ.len() && occ[j].0 == run_end {
                run_end = occ[j].1;
                j += 1;
