            fields.push(line[last..*s].to_string());
            // delimiter run string is line[*s..*e]
            delims.push(line[*s..*e].to_string());
            last = *e;
        }
        fields.push(line[last..].to_string());
    }

    FieldSlice { fields, delimiters: delims }
}

