fn resolve_bounds_for_n(bounds: &[BoundItem], n: usize, fallback_oob: &Option<String>) -> Result<Vec<ResolvedBound>, String> {
    // n = total fields
    // For each bound item, resolve left/right to positions.
    // Returns list of resolved ranges (start,end inclusive 1-indexed) or single with fallback handling.
