    //   Right OOB: clamp.
    //   Left>right after resolution => if fallback, return fallback, else error left>right (runtime).

    let mut result = Vec::new();

    for item in bounds {
        match item {
            BoundItem::Single { value, fallback, raw } => {
                let pos = if *value > 0 {
                    *value as usize
                } else {
                    // negative
