                            // We'll create a special resolved where start=end=0 and fallback present, indicating OOB fallback.
                            result.push(ResolvedBound { start: 0, end: 0, fallback: fb, raw: raw.clone(), is_single: true });
                            continue;
                        } else {
                            return Err(format!("Error: Out of bounds: {}", raw));
                        }
                    } else {
                        p as usize
                    }
                };
                if pos == 0 || pos > n {
                    // OOB positive
                    let fb = if fallback.is_some() { fallback.clone() } else { fallback_oob.clone() };
                    if fb.is_some() {
                        result.push(ResolvedBound { start: 0, end: 0, fallback: fb, raw: raw.clone(), is_single: true });
                        continue;
                    } else {
                        return Err(format!("Error: Out of bounds: {}", raw));
                    }
                } else {
                    result.push(ResolvedBound { start: pos, end: pos, fallback: fallback.clone(), raw: raw.clone(), is_single: true });
                }
