                        } else {
                            Some(lv as usize)
                        }
                    } else {
                        let p = n as i64 + lv + 1;
                        if p < 1 {
                            None
                        } else {
                            Some(p as usize)
                        }
                    }
                };

                // Resolve right with clamping
                let right_pos_opt: Option<usize> = if right.is_none() {
                    Some(n)
                } else {
                    let rv = right_val;
                    if rv > 0 {
                        if rv as usize > n {
                            Some(n) // clamp
                        } else {
                            Some(rv as usize)
                        }
                    } else {
                        let p = n as i64 + rv + 1;
                        if p < 1 {
                            Some(1) // clamp to 1 per observations
                        } else {
                            Some(p as usize)
                        }
                    }
                };

