                        // Good.
                        // For case where left is within but left>right after conversion (e.g., "2:-2" with n=2): left=2, right=-2 => right_pos=1, left>right => error "Field left value cannot be greater than right value" (not OOB). That's separate.

                        // For left OOB error:
                        return Err(format!("Error: Out of bounds: {}", left_val));
                    }
                }

                let left_pos = left_pos_opt.unwrap();
                let right_pos = right_pos_opt.unwrap();

                if left_pos > right_pos {
                    // left > right
                    let fb = if fallback.is_some() { fallback.clone() } else { fallback_oob.clone() };
                    if fb.is_some() {
                        result.push(ResolvedBound { start: 0, end: 0, fallback: fb, raw: raw.clone(), is_single: false });
                        continue;
                    } else {
                        return Err(format!("Error: Field left value cannot be greater than right value"));
                    }
                }

                result.push(ResolvedBound { start: left_pos, end: right_pos, fallback: fallback.clone(), raw: raw.clone(), is_single: false });
            }
        }
    }

    Ok(result)
}

