#[derive(Debug, Clone)]
struct SingleBound {
    value: i64,
}

#[derive(Debug, Clone)]
struct RangeBound {
    left: Option<i64>,
    right: Option<i64>,
    fallback: Option<String>,
    raw: String, // original token for error messages
    // For error reporting of OOB, we need to know original token
}

#[derive(Debug, Clone)]
enum BoundItem {
    Single { value: i64, fallback: Option<String>, raw: String },
    Range { left: Option<i64>, right: Option<i64>, fallback: Option<String>, raw: String },
}

fn parse_range_token(token: &str, full_original: &str) -> Result<BoundItem, String> {
    // token is like "1", "-1", "1:", ":2", "1:3", "1:3=fb", "1=fb", ":2=fb", etc
    // Contains first '=' split
    let (main_part, fallback) = if let Some(eq_idx) = token.find('=') {
        (&token[..eq_idx], Some(token[eq_idx+1..].to_string()))
    } else {
        (token, None)
    };
    if main_part.is_empty() {
        return Err(format!("failed to parse '{}': Field format error: empty field", full_original));
    }
    if main_part.contains(':') {
        // range
        let colon_idx = main_part.find(':').unwrap();
        let left_str = &main_part[..colon_idx];
        let right_str = &main_part[colon_idx+1..];
        if left_str.is_empty() && right_str.is_empty() {
            return Err(format!("failed to parse '{}': Field format error, no numbers next to `:`", full_original));
        }
        let left_opt = if left_str.is_empty() {
            None
        } else {
            match left_str.parse::<i64>() {
                Ok(v) => {
                    if v == 0 {
                        return Err(format!("failed to parse '{}': Zero is not a valid field", full_original));
                    }
                    Some(v)
                },
                Err(_) => {
                    return Err(format!("failed to parse '{}': Not a number `{}`", full_original, left_str));
                }
            }
        };
        let right_opt = if right_str.is_empty() {
            None
        } else {
            match right_str.parse::<i64>() {
                Ok(v) => {
                    if v == 0 {
                        return Err(format!("failed to parse '{}': Zero is not a valid field", full_original));
                    }
                    Some(v)
                },
                Err(_) => {
                    return Err(format!("failed to parse '{}': Not a number `{}`", full_original, right_str));
                }
            }
        };
        if let (Some(l), Some(r)) = (left_opt, right_opt) {
            if l > 0 && r > 0 && l > r {
                return Err(format!("failed to parse '{}': Field left value cannot be greater than right value", full_original));
            }
            if l < 0 && r < 0 && l > r {
                return Err(format!("failed to parse '{}': Field left value cannot be greater than right value", full_original));
            }
        }
        Ok(BoundItem::Range { left: left_opt, right: right_opt, fallback, raw: token.to_string() })
    } else {
        // single
        match main_part.parse::<i64>() {
            Ok(v) => {
                if v == 0 {
                    return Err(format!("failed to parse '{}': Zero is not a valid field", full_original));
                }
                Ok(BoundItem::Single { value: v, fallback, raw: token.to_string() })
            },
            Err(_) => {
                Err(format!("failed to parse '{}': Not a number `{}`", full_original, main_part))
            }
        }
    }
}

fn parse_bounds_list(full: &str) -> Result<Vec<BoundItem>, String> {
    if full.is_empty() {
        return Err(format!("failed to parse '': Field format error: empty field"));
    }
    // check empty parts like "1,,2"
    if full.contains(",,") || full.starts_with(',') || full.ends_with(',') {
        // need to detect empty token
        let parts: Vec<&str> = full.split(',').collect();
        for p in &parts {
            if p.is_empty() {
                return Err(format!("failed to parse '{}': Field format error: empty field", full));
            }
        }
    }
    let parts: Vec<&str> = full.split(',').collect();
    let mut res = Vec::new();
    for p in parts {
        if p.is_empty() {
            return Err(format!("failed to parse '{}': Field format error: empty field", full));
        }
        // For format detection inside? But this function is for plain bounds list, not format.
        // However inside format placeholders we also call this? Actually placeholders may contain comma separated bounds.
        // So this same parser works for placeholder content which may contain "=" and ":".
        // But if placeholder content contains braces, that's error.
        if p.contains('{') || p.contains('}') {
            // Check specific error cases for format detection:
            // If it contains braces, we should attempt to parse as format? But this function is called for plain bounds list, so braces would be invalid number.
            // However original gives specific errors like missing closing parenthesis etc for "{1" etc.
            // We'll handle at higher level.
            // For now, if it contains '{' or '}', return appropriate error based on original's messages.
            if p == "{}" {
                return Err(format!("failed to parse '{}': Field format error: empty field", full));
            }
            if p.starts_with('{') && !p.contains('}') {
                return Err(format!("failed to parse '{}': Field format error: missing closing parenthesis", full));
            }
            if !p.starts_with('{') && p.contains('}') {
                return Err(format!("failed to parse '{}': Field format error: missing opening parenthesis", full));
            }
            // If it's like "{{{1}}}" etc, the content after stripping? We need to handle but for plain bounds list, any brace containing should be "Not a number"
            // Actually original for "{{{1}}}" gave Not a number `1}}` which suggests it did parse as format? So this path may not be reached for that case because format detection happens before bounds parsing.
        }
        let item = parse_range_token(p, full)?;
        res.push(item);
    }
    if res.is_empty() {
        // mimic panic? But we will return error that will be turned into panic per original?
        // For "{{}}" case original panicked. We need to detect that case in format parsing, not here.
        return Err("UserBoundsList must contain at least one UserBounds".to_string());
    }
    Ok(res)
}

// Format template parsing
#[derive(Debug, Clone)]
enum FormatPart {
    Lit(String),
    Placeholder(Vec<BoundItem>), // bounds inside {}
}

fn parse_format_template(s: &str) -> Result<Vec<FormatPart>, String> {
    // Returns error messages matching original for some cases, or panics for empty bounds list.
    // We need to handle {{ and }} escaping.
    // Algorithm: scan sequentially.
    // If we see "{{", it's escaped '{' -> literal '{'
    // If we see "}}", escaped '}' -> literal '}'
    // If we see '{', start placeholder until next '}' (first). If no next '}', error missing closing.
    // If we see '}' not part of escape and not closing a placeholder, error missing opening.
    // However need to handle that inside placeholder, there could be "}}" that is not escape? Original behavior for "{{{1}}}" suggests that inside placeholder, "}}" is NOT treated as escape, so it becomes part of content leading to parse error.
    // So for simplicity: outside placeholder, handle {{ and }}.
    // Inside placeholder, just search for next '}' (first).
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    let mut parts: Vec<FormatPart> = Vec::new();
    let mut lit_buf = String::new();
    let mut has_placeholder = false;

    while i < chars.len() {
        if chars[i] == '{' {
            if i+1 < chars.len() && chars[i+1] == '{' {
                // escaped
                lit_buf.push('{');
                i += 2;
                continue;
            } else {
                // start placeholder
                // flush lit
                if !lit_buf.is_empty() {
                    parts.push(FormatPart::Lit(lit_buf.clone()));
                    lit_buf.clear();
                }
                // find next '}'
                let mut j = i+1;
                let mut found = None;
                while j < chars.len() {
                    if chars[j] == '}' {
                        // check if this is part of "}}" escape? For placeholder end, we should NOT treat "}}" as escape inside placeholder? Let's see: for "{{}} {1}", we have "{{" escape, then "}}" escape. That's outside placeholder. Inside placeholder, if there is "}}", what should happen? Original gave error for "{{{1}}}" where content "1}}" includes "}}". So they did NOT treat "}}" inside placeholder as escape. So we should simply take first '}' as closing, regardless of following char.
                        found = Some(j);
                        break;
                    }
                    j += 1;
                }
                if let Some(close_idx) = found {
                    let content: String = chars[i+1..close_idx].iter().collect();
                    if content.is_empty() {
                        return Err(format!("failed to parse '{}': Field format error: empty field", s));
                    }
                    // content may contain spaces -> will be caught as Not a number
                    // Parse content as bounds list? Actually content like "1" or "1:2" or "1,2=fb" etc. It can be multiple bounds separated by comma.
                    // The original for "{1,2}" gave output for 2 fields. So content inside {} can be comma separated list.
                    // We'll parse it with parse_bounds_list but using content as full_original? However error messages should reference the outer format string s, not just content. For example, error for "{{{1}}}" says failed to parse '{{{1}}}': Not a number `1}}` . So the outer string is "{{{1}}}" and failing token inside is "1}}". That matches if we parse content "1}}" as bounds and error message includes outer s.
                    // So we need to parse content with error messages that reference outer s? Actually parse_range_token error uses full_original as second arg. So if we call parse_range_token with content's token but full_original = s, we would get error referencing s, with failing token being content's part. That matches.
                    // Let's attempt: parse content "1}}" as bounds list. It contains no comma, no colon, so single token "1}}". parse_range_token for "1}}" -> main_part "1}}" (no "=") -> parse as i64 fails -> Not a number `1}}`. Error message would be "failed to parse '{{{1}}}': Not a number `1}}`" if we pass full_original = s. That matches observed!

                    // So we can parse content as bounds list using s as full_original for error messages.

                    // However content could be multiple bounds like "1,2" => split by comma, each token parsed.

                    match parse_bounds_list_with_outer(&content, s) {
                        Ok(bounds) => {
                            has_placeholder = true;
                            parts.push(FormatPart::Placeholder(bounds));
                        },
                        Err(e) => {
                            // If error is from bounds parsing, propagate
                            return Err(e);
                        }
                    }
                    i = close_idx + 1;
                } else {
                    return Err(format!("failed to parse '{}': Field format error: missing closing parenthesis", s));
                }
            }
        } else if chars[i] == '}' {
            if i+1 < chars.len() && chars[i+1] == '}' {
                lit_buf.push('}');
                i += 2;
                continue;
            } else {
                // stray }
                return Err(format!("failed to parse '{}': Field format error: missing opening parenthesis", s));
            }
        } else {
            lit_buf.push(chars[i]);
            i += 1;
        }
    }
    if !lit_buf.is_empty() {
        parts.push(FormatPart::Lit(lit_buf));
    }
    if !has_placeholder {
        // Original panicked with UserBoundsList must contain at least one UserBounds
        // We will panic with same message to match original behavior (though ideally should error)
        panic!("UserBoundsList must contain at least one UserBounds");
    }
    Ok(parts)
}

fn parse_bounds_list_with_outer(inner: &str, outer: &str) -> Result<Vec<BoundItem>, String> {
    // inner is content inside {}, outer is full format string for error messages.
    // inner may contain commas.
    if inner.is_empty() {
        return Err(format!("failed to parse '{}': Field format error: empty field", outer));
    }
    // Check empty tokens
    let parts: Vec<&str> = inner.split(',').collect();
    let mut res = Vec::new();
    for p in parts {
        if p.is_empty() {
            return Err(format!("failed to parse '{}': Field format error: empty field", outer));
        }
        // p may contain braces? That would be error missing opening/closing?
        if p.contains('{') || p.contains('}') {
            if p == "" {
                return Err(format!("failed to parse '{}': Field format error: empty field", outer));
            }
            // If it contains '{' starting, missing closing?
            // For simplicity, if contains '{' or '}', treat as missing parenthesis errors.
            if p.contains('{') && !p.contains('}') {
                return Err(format!("failed to parse '{}': Field format error: missing closing parenthesis", outer));
            }
            if !p.contains('{') && p.contains('}') {
                return Err(format!("failed to parse '{}': Field format error: missing opening parenthesis", outer));
            }
            // Otherwise, attempt to parse as number will fail with Not a number.
        }
        let item = parse_range_token(p, outer)?;
        res.push(item);
    }
    Ok(res)
}

fn is_format_string(s: &str) -> bool {
    // Heuristic: contains '{' or '}' that is not escaped? Simplistic: contains '{' or '}'.
    // But original: "hello" (no braces) is NOT format, it's parsed as bounds and fails.
    // "{1}" is format.
    // "{{}}" contains braces but is escaped? It contains braces, and is considered format that panics (no placeholder). So we treat any string containing '{' or '}' as format attempt.
    // Actually "1}": contains '}' but error missing opening, which is format error.
    // So detection: if string contains '{' or '}' -> treat as format? Let's see: "1,2" contains no braces, it's plain.
    // What about string like "a{1}b"? Contains braces, format.
    // So if contains '{' or '}' => format, else plain.
    s.contains('{') || s.contains('}')
}

fn json_escape(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0C}' => out.push_str("\\f"),
            c if c.is_control() => {
                out.push_str(&format!("\\u{:04x}", c as u32));
            },
            _ => out.push(c),
        }
    }
    out
}

