#[derive(Debug, Clone)]
struct FieldSlice {
    fields: Vec<String>,
    // For join with original delimiters, we need to know delimiters between fields.
    // For string delimiter, we can store the delimiter occurrences.
    // For greedy/compress, we need also the run strings.
    // We'll store delimiters: Vec<String> where len = fields.len() -1 (could be empty for 1 field)
    // Each entry is the delimiter string that was between fields (could be e.g., ":" or "::" or "--" or "----")
    // For normal split, each delimiter is exactly the delimiter pattern (e.g., ":")
    // For greedy/compress, each delimiter is the full run of consecutive delimiters (e.g., "::" or "----")
    delimiters: Vec<String>, // original delimiter runs
}

fn split_by_string_delim(line: &str, delim: &str, greedy: bool, compress: bool) -> FieldSlice {
    if delim.is_empty() {
        // Original: empty delimiter gave output whole line? From earlier: echo "abc" | -d "" -f 1 => empty? Actually it gave empty? We saw it gave empty? Let's re-evaluate: echo "abc" | -d "" -f 1 gave? The test showed empty? It showed nothing? The command "echo "abc" | ./executable -d "" -f 1" gave blank? Actually earlier output was empty line. So treat empty delimiter as no split? We'll treat as not splitting: single field = whole line.
        return FieldSlice { fields: vec![line.to_string()], delimiters: vec![] };
    }
    // For greedy/compress, we need to find runs of delimiter.
    // Approach: find all occurrences of delim (non-overlapping) scanning left to right.
    // Then group consecutive occurrences where end == next start (i.e., adjacent).
    // For delim ":" and line "a::b::c", occurrences at pos 1,2,4,5? Actually "a::b::c": indices: 0:a,1::,2::,3:b,4::,5::,6:c . Occurrences at 1 and 2 are consecutive (since delim len 1, end 2 == start 2). So they form a run of 2 delimiters: "::" from 1 to 2.
    // Similarly second run at 4-5.
    // For delim "--" and "a----b": string a----b: a at0, delim at1-2 "--", delim at3-4 "--", b at5. So occurrences at 1 and 3 consecutive (since 1+2=3). So run length 2 => "----".

    // For normal mode, we just split at each occurrence individually.

    // For greedy/compress mode, we collapse runs into one separator.

    let mut fields: Vec<String> = Vec::new();
    let mut delims: Vec<String> = Vec::new();

    let mut occ: Vec<(usize, usize)> = Vec::new(); // (start, end)
    let mut search_start = 0;
    while search_start <= line.len() {
        if let Some(pos) = line[search_start..].find(delim) {
            let abs_start = search_start + pos;
            let abs_end = abs_start + delim.len();
            occ.push((abs_start, abs_end));
            search_start = abs_end; // non-overlapping
        } else {
            break;
        }
    }

    if occ.is_empty() {
        return FieldSlice { fields: vec![line.to_string()], delimiters: vec![] };
    }

    if !greedy && !compress {
        // normal: split at each occurrence
        let mut last = 0;
        for (s,e) in &occ {
            fields.push(line[last..*s].to_string());
            delims.push(delim.to_string());
            last = *e;
        }
        fields.push(line[last..].to_string());
        // delims len = fields-1, which is occ.len()
        // But we have delims as delim each time, correct.
    } else {
        // greedy/compress: group consecutive
        let mut grouped: Vec<(usize, usize)> = Vec::new(); // run start, run end
        let mut i = 0;
        while i < occ.len() {
            let mut run_start = occ[i].0;
            let mut run_end = occ[i].1;
            let mut j = i+1;
            while j < occ.len() && occ[j].0 == run_end {
                run_end = occ[j].1;
                j += 1;
            }
            // run from run_start to run_end
            grouped.push((run_start, run_end));
            i = j;
        }
        // Now split at grouped runs
        let mut last = 0;
        for (s,e) in &grouped {
            fields.push(line[last..*s].to_string());
            // delimiter run string is line[*s..*e]
            delims.push(line[*s..*e].to_string());
            last = *e;
        }
        fields.push(line[last..].to_string());
    }

    FieldSlice { fields, delimiters: delims }
}

