    // Let's implement greedy for regex similar to string: group consecutive matches where start == previous end.
    // Then fields split at grouped runs.

    // Group matches into runs where consecutive.
    let mut grouped_runs: Vec<(usize, usize)> = Vec::new();
    let mut i = 0;
