}

fn split_line(line: &str, delim_info: &DelimInfo, greedy: bool, compress: bool) -> FieldSlice {
    if delim_info.is_regex {
        let re = delim_info.regex.as_ref().unwrap();
        if greedy || compress {
            // group consecutive matches
            let mut matches: Vec<(usize, usize)> = Vec::new();
            for m in re.find_iter(line) {
                matches.push((m.start(), m.end()));
            }
            if matches.is_empty() {
                return FieldSlice { fields: vec![line.to_string()], delimiters: vec![] };
            }
            let mut grouped: Vec<(usize, usize)> = Vec::new();
            let mut i = 0;
            while i < matches.len() {
                let mut rs = matches[i].0;
                let mut re_end = matches[i].1;
                let mut j = i+1;
                while j < matches.len() && matches[j].0 == re_end {
                    re_end = matches[j].1;
                    j += 1;
                }
                grouped.push((rs, re_end));
                i = j;
            }
            let mut fields = Vec::new();
            let mut delims = Vec::new();
            let mut last = 0;
            for (s,e) in &grouped {
                fields.push(line[last..*s].to_string());
                delims.push(line[*s..*e].to_string());
                last = *e;
            }
            fields.push(line[last..].to_string());
            FieldSlice { fields, delimiters: delims }
        } else {
            split_by_regex_delim(line, re, None, false)
        }
    } else {
        split_by_string_delim(line, &delim_info.pattern, greedy, compress)
    }
}

#[derive(Debug, Clone, Copy)]
enum TrimType { Left, Right, Both }

fn trim_line(line: &str, delim_info: &DelimInfo, trim: TrimType) -> String {
    // Trim is greedy per doc
    if delim_info.is_regex {
        let re = delim_info.regex.as_ref().unwrap();
        let mut s = line.to_string();
        // Trim left: while matches at start
        if matches!(trim, TrimType::Left | TrimType::Both) {
            loop {
                if let Some(m) = re.find(&s) {
                    if m.start() == 0 {
                        s = s[m.end()..].to_string();
                    } else {
                        break;
                    }
                } else {
                    break;
                }
            }
        }
        if matches!(trim, TrimType::Right | TrimType::Both) {
            loop {
                if let Some(m) = re.find(&s) {
                    // Need to find match at end: we need to find last match that ends at end of string
                    // Use re.find_iter and check if any ends at len
                    let mut found_end = None;
                    for mm in re.find_iter(&s) {
                        if mm.end() == s.len() {
                            found_end = Some(mm);
                        }
                    }
                    if let Some(mm) = found_end {
                        s = s[..mm.start()].to_string();
                    } else {
                        break;
                    }
                } else {
                    break;
                }
            }
        }
        s
    } else {
        let delim = &delim_info.pattern;
        if delim.is_empty() {
            return line.to_string();
        }
        let mut s = line.to_string();
        if matches!(trim, TrimType::Left | TrimType::Both) {
            while s.starts_with(delim) {
                s = s[delim.len()..].to_string();
            }
        }
        if matches!(trim, TrimType::Right | TrimType::Both) {
            while s.ends_with(delim) {
                s = s[..s.len() - delim.len()].to_string();
            }
        }
        s
    }
}

fn compress_delimiters(line: &str, delim_info: &DelimInfo) -> String {
    // -p: print only first delimiter of sequence: replace each maximal consecutive run of delimiters with single delimiter (first).
    // For string delimiter, we already handle grouping but need to reconstruct string with compressed delimiters.
    // For regex, need to replace runs with first match's string? Or with something? The doc says print only first delimiter of a sequence.
    // For regex delimiter, compress means replace each run of consecutive delimiter matches with first match's string? Let's implement.
    if delim_info.is_regex {
        let re = delim_info.regex.as_ref().unwrap();
        // Find matches, group consecutive, replace each group with first match's string (or first? but need first delimiter of sequence)
        // We'll build result.
        let mut result = String::new();
        let mut last = 0;
        let matches: Vec<_> = re.find_iter(line).collect();
        let mut i = 0;
        while i < matches.len() {
            let m0 = &matches[i];
            // start of run
            let run_start = m0.start();
            let mut run_end = m0.end();
            let mut j = i+1;
            while j < matches.len() && matches[j].start() == run_end {
                run_end = matches[j].end();
                j += 1;
            }
            // push text before run
            result.push_str(&line[last..run_start]);
            // push first delimiter (m0) only
            result.push_str(&line[m0.start()..m0.end()]);
            last = run_end;
            i = j;
        }
        result.push_str(&line[last..]);
        result
    } else {
        let delim = &delim_info.pattern;
        if delim.is_empty() {
            return line.to_string();
        }
        // Find occurrences and group
        let mut occ: Vec<(usize, usize)> = Vec::new();
        let mut search = 0;
        while search <= line.len() {
            if let Some(pos) = line[search..].find(delim) {
                let s = search + pos;
                let e = s + delim.len();
                occ.push((s,e));
                search = e;
            } else { break; }
        }
        if occ.is_empty() { return line.to_string(); }
        // group consecutive
        let mut grouped: Vec<(usize, usize)> = Vec::new();
        let mut i = 0;
        while i < occ.len() {
            let mut rs = occ[i].0;
            let mut re = occ[i].1;
            let mut j = i+1;
            while j < occ.len() && occ[j].0 == re {
                re = occ[j].1;
                j += 1;
            }
            grouped.push((rs, re));
            i = j;
        }
        let mut result = String::new();
        let mut last = 0;
        for (s,e) in grouped {
            result.push_str(&line[last..s]);
            result.push_str(delim); // first delimiter only
            last = e;
        }
        result.push_str(&line[last..]);
        result
    }
}

fn parse_trim_type(s: &str) -> Result<TrimType, String> {
    match s {
        "l" | "L" => Ok(TrimType::Left),
        "r" | "R" => Ok(TrimType::Right),
        "b" | "B" => Ok(TrimType::Both),
        _ => Err(format!("failed to parse '{}': Valid trim values are (l|L)eft, (r|R)ight, (b|B)oth", s)),
    }
}

