#[derive(Debug, Clone)]
struct ResolvedBound {
    start: usize, // 1-indexed inclusive after resolution? We'll use 0-indexed inclusive for fields vec?
    end: usize,
    fallback: Option<String>,
    raw: String,
    is_single: bool,
}

fn resolve_bounds_for_n(bounds: &[BoundItem], n: usize, fallback_oob: &Option<String>) -> Result<Vec<ResolvedBound>, String> {
    // n = total fields
    // For each bound item, resolve left/right to positions.
    // Returns list of resolved ranges (start,end inclusive 1-indexed) or single with fallback handling.
    // This is for fields mode.

    // For error handling:
    // - If single field OOB: if fallback in item or generic fallback_oob, use fallback as resolved with fallback, not error.
    //   Actually for single OOB with fallback, we return resolved with fallback?
    // - If range OOB: as discussed, left OOB => if fallback, return fallback, else error.
    //   Right OOB: clamp.
    //   Left>right after resolution => if fallback, return fallback, else error left>right (runtime).

    let mut result = Vec::new();

    for item in bounds {
        match item {
            BoundItem::Single { value, fallback, raw } => {
                let pos = if *value > 0 {
                    *value as usize
                } else {
                    // negative
                    // n as i64 + value +1
                    let n_i = n as i64;
                    let p = n_i + *value + 1;
                    if p < 1 {
                        // out of bounds negative
                        // Check fallback
                        let fb = if fallback.is_some() { fallback.clone() } else { fallback_oob.clone() };
                        if fb.is_some() {
                            // For single OOB with fallback, we will create a resolved that is fallback? Actually we need to return fallback as field.
                            // We'll create a special resolved where start=end=0 and fallback present, indicating OOB fallback.
                            result.push(ResolvedBound { start: 0, end: 0, fallback: fb, raw: raw.clone(), is_single: true });
                            continue;
                        } else {
                            return Err(format!("Error: Out of bounds: {}", raw));
                        }
                    } else {
                        p as usize
                    }
                };
                if pos == 0 || pos > n {
                    // OOB positive
                    let fb = if fallback.is_some() { fallback.clone() } else { fallback_oob.clone() };
                    if fb.is_some() {
                        result.push(ResolvedBound { start: 0, end: 0, fallback: fb, raw: raw.clone(), is_single: true });
                        continue;
                    } else {
                        return Err(format!("Error: Out of bounds: {}", raw));
                    }
                } else {
                    result.push(ResolvedBound { start: pos, end: pos, fallback: fallback.clone(), raw: raw.clone(), is_single: true });
                }
            },
            BoundItem::Range { left, right, fallback, raw } => {
                // left None => 1, right None => n
                let left_val = left.unwrap_or(1);
                let right_val = right.unwrap_or(n as i64);

                // Resolve left
                let left_pos_opt: Option<usize> = if left.is_none() {
                    Some(1)
                } else {
                    let lv = left_val;
                    if lv > 0 {
                        if lv as usize > n {
                            // left OOB positive
                            None
                        } else {
                            Some(lv as usize)
                        }
                    } else {
                        let p = n as i64 + lv + 1;
                        if p < 1 {
                            None
                        } else {
                            Some(p as usize)
                        }
                    }
                };

                // Resolve right with clamping
                let right_pos_opt: Option<usize> = if right.is_none() {
                    Some(n)
                } else {
                    let rv = right_val;
                    if rv > 0 {
                        if rv as usize > n {
                            Some(n) // clamp
                        } else {
                            Some(rv as usize)
                        }
                    } else {
                        let p = n as i64 + rv + 1;
                        if p < 1 {
                            Some(1) // clamp to 1 per observations
                        } else {
                            Some(p as usize)
                        }
                    }
                };

                // Now check left OOB
                if left_pos_opt.is_none() {
                    // left OOB
                    let fb = if fallback.is_some() { fallback.clone() } else { fallback_oob.clone() };
                    if fb.is_some() {
                        result.push(ResolvedBound { start: 0, end: 0, fallback: fb, raw: raw.clone(), is_single: false });
                        continue;
                    } else {
                        // error out of bounds: left
                        // For error message, what to show? Original for range OOB showed "Error: Out of bounds: 3" or "Error: Out of bounds: 1:10" etc? Let's see:
                        // For range "3:10" with n=2, error was "Error: Out of bounds: 3" (just left value, not full range). For "1:10" with lines, error was "Error: Out of bounds: 1:10" (full range). So error format differs for lines vs fields?
                        // For fields, we saw: "a:b" with "3:10" => Error: Out of bounds: 3 (not 3:10). For "a:b" with "5:6" => Error: Out of bounds: 5
                        // For lines: "a\nb\n" with "1:10" => Error: Out of bounds: 1:10
                        // So for fields, error shows left value only when left OOB? But for lines, shows whole range.
                        // We'll implement for fields: error shows left raw if left OOB? Actually raw is like "3:10" but error shows "3". So need to show left token?
                        // Original code for fields range OOB: they said "Error: Out of bounds: 3" for "3:10". So they show left value only? Let's check other: "1:10" with lines gave "1:10", with fields gave no error (clamped). So for fields left OOB error shows left, not full range.
                        // For simplicity, we'll show the raw bound that is OOB? For single field OOB we show raw. For range left OOB, we should show left value? The left value is left_opt. For "3:10", left=3. So error "Error: Out of bounds: 3". For "5:6", left=5 => error 5. For "-10:2", left=-10 => error -10. So we can produce error with left value.
                        // We'll construct error as "Error: Out of bounds: {}" where {} is left raw if left OOB else right? For range, left OOB case, show left.
                        // If left is None (open) can't be OOB. So left OOB positive >n: show left value (e.g., 3). If left negative OOB (< -n): show left (e.g., -10).
                        // So error message: format!("Error: Out of bounds: {}", left_val) where left_val is original left? For "-10:2", left_val -10, error shows -10.
                        // Good.
                        // For case where left is within but left>right after conversion (e.g., "2:-2" with n=2): left=2, right=-2 => right_pos=1, left>right => error "Field left value cannot be greater than right value" (not OOB). That's separate.

                        // For left OOB error:
                        return Err(format!("Error: Out of bounds: {}", left_val));
                    }
                }

                let left_pos = left_pos_opt.unwrap();
                let right_pos = right_pos_opt.unwrap();

                if left_pos > right_pos {
                    // left > right
                    let fb = if fallback.is_some() { fallback.clone() } else { fallback_oob.clone() };
                    if fb.is_some() {
                        result.push(ResolvedBound { start: 0, end: 0, fallback: fb, raw: raw.clone(), is_single: false });
                        continue;
                    } else {
                        return Err(format!("Error: Field left value cannot be greater than right value"));
                    }
                }

                result.push(ResolvedBound { start: left_pos, end: right_pos, fallback: fallback.clone(), raw: raw.clone(), is_single: false });
            }
        }
    }

    Ok(result)
}

