                    },
                    _ => {}
                }
                i+=1;
                continue;
            } else {
                // combined pure flags
                let flag_chars = &arg[1..];
                if flag_chars.chars().all(|c| "gpszmj".contains(c)) {
                    for ch in flag_chars.chars() {
                        match ch {
                            'g' => {
                                if greedy { eprintln!("tuc: unexpected arguments: [\"-g\"]\nTry 'tuc --help' for more information."); process::exit(1); }
                                greedy=true;
                            },
                            'p' => {
                                if compress { eprintln!("tuc: unexpected arguments: [\"-p\"]\nTry 'tuc --help' for more information."); process::exit(1); }
                                compress=true;
                            },
                            's' => {
                                if only_delimited { eprintln!("tuc: unexpected arguments: [\"-s\"]\nTry 'tuc --help' for more information."); process::exit(1); }
