                if lines_opt.is_some() { eprintln!("tuc: unexpected arguments: [\"{}\", \"{}\"]\nTry 'tuc --help' for more information.", arg, args[i+1]); process::exit(1); }
                lines_opt=Some(args[i+1].clone()); i+=1;
            },
            "-d" | "--delimiter" => {
                if i+1>=args.len() { eprintln!("the '-d' option doesn't have an associated value"); process::exit(1); }
                if delimiter_opt.is_some() || regex_opt.is_some() { eprintln!("tuc: unexpected arguments: [\"{}\", \"{}\"]\nTry 'tuc --help' for more information.", arg, args[i+1]); process::exit(1); }
                delimiter_opt=Some(args[i+1].clone()); i+=1;
            },
            "-e" | "--regex" => {
                if i+1>=args.len() { eprintln!("the '-e' option doesn't have an associated value"); process::exit(1); }
                if delimiter_opt.is_some() || regex_opt.is_some() { eprintln!("tuc: unexpected arguments: [\"{}\", \"{}\"]\nTry 'tuc --help' for more information.", arg, args[i+1]); process::exit(1); }
                regex_opt=Some(args[i+1].clone()); i+=1;
            },
            "-r" | "--replace-delimiter" => {
                if i+1>=args.len() { eprintln!("the '-r' option doesn't have an associated value"); process::exit(1); }
                if replace_opt.is_some() { eprintln!("tuc: unexpected arguments: [\"{}\", \"{}\"]\nTry 'tuc --help' for more information.", arg, args[i+1]); process::exit(1); }
                replace_opt=Some(args[i+1].clone()); i+=1;
            },
            "-t" | "--trim" => {
                if i+1>=args.len() { eprintln!("the '-t' option doesn't have an associated value"); process::exit(1); }
                if trim_opt.is_some() { eprintln!("tuc: unexpected arguments: [\"{}\", \"{}\"]\nTry 'tuc --help' for more information.", arg, args[i+1]); process::exit(1); }
                trim_opt=Some(args[i+1].clone()); i+=1;
            },
            "--fallback-oob" => {
                if i+1>=args.len() { eprintln!("the '--fallback-oob' option doesn't have an associated value"); process::exit(1); }
                if fallback_oob_opt.is_some() { eprintln!("tuc: unexpected arguments: [\"{}\", \"{}\"]\nTry 'tuc --help' for more information.", arg, args[i+1]); process::exit(1); }
                fallback_oob_opt=Some(args[i+1].clone()); i+=1;
            },
            "-M" | "--fixed-memory" => {
                if i+1>=args.len() { eprintln!("the '-M' option doesn't have an associated value"); process::exit(1); }
                if fixed_memory_opt.is_some() { eprintln!("tuc: unexpected arguments: [\"{}\", \"{}\"]\nTry 'tuc --help' for more information.", arg, args[i+1]); process::exit(1); }
                fixed_memory_opt=Some(args[i+1].clone()); i+=1;
            },
            _ => {
                if arg.starts_with('-') {
                    eprintln!("tuc: unexpected arguments: [\"{}\"]\nTry 'tuc --help' for more information.", arg);
                    process::exit(1);
                } else {
                    if filepath.is_some() {
                        eprintln!("tuc: unexpected arguments: [\"{}\", \"{}\"]\nTry 'tuc --help' for more information.", filepath.as_ref().unwrap(), arg);
                        process::exit(1);
                    }
                    filepath=Some(arg.clone());
                }
            }
        }
        i+=1;
    }

    // Mode
    let mut mode = Mode::Fields;
    let mut bounds_str_opt: Option<String> = None;
    if fields_opt.is_some() {
        mode = Mode::Fields;
        bounds_str_opt = fields_opt.clone();
    } else if bytes_opt.is_some() {
        mode = Mode::Bytes;
        bounds_str_opt = bytes_opt.clone();
    } else if chars_opt.is_some() {
        mode = Mode::Chars;
        bounds_str_opt = chars_opt.clone();
    } else if lines_opt.is_some() {
        mode = Mode::Lines;
        bounds_str_opt = lines_opt.clone();
    } else {
        mode = Mode::Fields;
        bounds_str_opt = Some("1:".to_string());
    }

    // Delim
    let delim_info = if let Some(pat) = regex_opt.clone() {
        match DelimInfo::new_regex(pat) {
            Ok(d) => d,
            Err(e) => { eprintln!("regex error: {}", e); process::exit(1); }
        }
    } else {
        let d = delimiter_opt.clone().unwrap_or("\t".to_string());
        DelimInfo::new_str(d)
    };

    let trim_type = if let Some(t) = trim_opt.clone() {
        match parse_trim_type(&t) {
            Ok(v) => Some(v),
            Err(e) => { eprintln!("{}", e); process::exit(1); }
        }
    } else { None };

    // join checks
