                                            if v>0 {
                                                if (v as usize) > split.fields.len() { None } else { Some(v as usize) }
                                            } else {
                                                let p = split.fields.len() as i64 + v +1;
                                                if p<1 || p> split.fields.len() as i64 { None } else { Some(p as usize) }
                                            }
                                        };
                                        if let Some(p) = pos_opt {
                                            elements.push(split.fields[p-1].clone());
                                        } else {
                                            let fb = fallback.clone().or(fallback_oob_opt.clone());
                                            if let Some(fb_str) = fb {
                                                elements.push(fb_str);
                                            } else {
                                                err_local = Some(format!("Error: Out of bounds: {}", raw));
                                                had_err=true;
                                                // For json partial: output "[" + elements joined with "," + "," ?

                                                // Build partial json
                                                let partial = if elements.is_empty() {
                                                    String::new()
                                                } else {
                                                    let inner = elements.iter().map(|e| format!("\"{}\"", json_escape(e))).collect::<Vec<_>>().join(",");
                                                    format!("[{},", inner)
                                                };
                                                if zero_terminated {
                                                    out_handle.write_all(partial.as_bytes()).unwrap();
                                                    out_handle.write_all(&[0]).unwrap();
                                                } else {
                                                    out_handle.write_all(partial.as_bytes()).unwrap();
                                                    out_handle.write_all(b"\n").unwrap();
                                                }
                                                eprintln!("{}", err_local.as_ref().unwrap());
                                                had_error_overall=true;
                                                break;
                                            }
                                        }
                                    },
                                    BoundItem::Range { left, right, fallback, raw } => {
                                        let left_val = left.unwrap_or(1);
                                        let right_val = right.unwrap_or(split.fields.len() as i64);
                                        let left_pos_opt = if left.is_none() { Some(1) } else {
                                            let lv=left_val;
                                            if lv>0 {
                                                if (lv as usize) > split.fields.len() { None } else { Some(lv as usize) }
                                            } else {
                                                let p = split.fields.len() as i64 + lv +1;
                                                if p<1 { None } else { Some(p as usize) }
                                            }
                                        };
                                        let right_pos_opt = if right.is_none() { Some(split.fields.len()) } else {
                                            let rv=right_val;
                                            if rv>0 {
                                                if (rv as usize) > split.fields.len() {
                                                    Some(split.fields.len())
                                                } else { Some(rv as usize) }
                                            } else {
                                                let p = split.fields.len() as i64 + rv +1;
                                                if p<1 { Some(1) } else { Some(p as usize) }
                                            }
                                        };

                                        if left_pos_opt.is_none() {
                                            let fb = fallback.clone().or(fallback_oob_opt.clone());
                                            if fb.is_some() {
                                                elements.push(fb.unwrap());
                                            } else {
                                                err_local = Some(format!("Error: Out of bounds: {}", left_val));
                                                had_err=true;
                                                // partial
                                                let partial = if elements.is_empty() {
                                                    String::new()
                                                } else {
                                                    let inner = elements.iter().map(|e| format!("\"{}\"", json_escape(e))).collect::<Vec<_>>().join(",");
                                                    format!("[{},", inner)
                                                };
                                                if zero_terminated {
                                                    out_handle.write_all(partial.as_bytes()).unwrap();
                                                    out_handle.write_all(&[0]).unwrap();
                                                } else {
                                                    out_handle.write_all(partial.as_bytes()).unwrap();
                                                    out_handle.write_all(b"\n").unwrap();
                                                }
                                                eprintln!("{}", err_local.as_ref().unwrap());
                                                had_error_overall=true;
                                                break;
                                            }
                                        } else {
                                            let lpos = left_pos_opt.unwrap();
                                            let rpos = right_pos_opt.unwrap();
                                            if lpos > rpos {
                                                let fb = fallback.clone().or(fallback_oob_opt.clone());
                                                if fb.is_some() {
                                                    elements.push(fb.unwrap());
                                                } else {
                                                    err_local = Some(format!("Error: Field left value cannot be greater than right value"));
                                                    had_err=true;
                                                    let partial = if elements.is_empty() {
                                                        String::new()
                                                    } else {
                                                        let inner = elements.iter().map(|e| format!("\"{}\"", json_escape(e))).collect::<Vec<_>>().join(",");
                                                        format!("[{},", inner)
                                                    };
                                                    if zero_terminated {
                                                        out_handle.write_all(partial.as_bytes()).unwrap();
                                                        out_handle.write_all(&[0]).unwrap();
                                                    } else {
                                                        out_handle.write_all(partial.as_bytes()).unwrap();
                                                        out_handle.write_all(b"\n").unwrap();
                                                    }
                                                    eprintln!("{}", err_local.as_ref().unwrap());
                                                    had_error_overall=true;
                                                    break;
                                                }
                                            } else {
                                                for p in lpos..=rpos {
                                                    elements.push(split.fields[p-1].clone());
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                            if had_err { break; }
                        }
                    };

                    // For json with complement
                    let final_elements = if complement {
                        // For complement json, we need to compute complement elements

                        // Resolve bounds for complement
                        let resolved = resolve_bounds(split.fields.len(), &bounds_list, &fallback_oob_opt).unwrap();
                        let mut selected_set = std::collections::HashSet::new();
                        for r in &resolved {
                            if r.start==0 { continue; }
                            for p in r.start..=r.end {
                                selected_set.insert(p);
                            }
                        }
                        let mut comp_elems = Vec::new();
                        for idx in 1..=split.fields.len() {
                            if !selected_set.contains(&idx) {
                                comp_elems.push(split.fields[idx-1].clone());
                            }
                        }
                        if comp_elems.is_empty() {
                            eprintln!("Error: the complement is empty");
                            had_error_overall=true;
                            continue;
                        }
                        comp_elems
                    } else {
                        // flatten resolved_for_json
                        let mut elems = Vec::new();
                        for res in &resolved_for_json {
                            if res.start==0 {
                                elems.push(res.fallback.clone().unwrap());
                            } else if res.is_range {
                                for p in res.start..=res.end {
                                    elems.push(split.fields[p-1].clone());
                                }
                            } else {
                                elems.push(split.fields[res.start-1].clone());
                            }
                        }
                        elems
                    };

                    let json_str = format!("[{}]", final_elements.iter().map(|e| format!("\"{}\"", json_escape(e))).collect::<Vec<_>>().join(","));
                    if zero_terminated {
                        out_handle.write_all(json_str.as_bytes()).unwrap();
                        out_handle.write_all(&[0]).unwrap();
                    } else {
                        out_handle.write_all(json_str.as_bytes()).unwrap();
                        out_handle.write_all(b"\n").unwrap();
                    }

                } else {
                    // plain

                    let final_line = if join_flag==Some(true) || replace_opt.is_some() {
                        let jd = replace_opt.clone().unwrap_or(if delim_info.is_regex { "".to_string() } else { delim_info.pattern.clone() });
                        // For plain fields, join pieces with jd
                        // But need to consider that range pieces already have internal delims (original or replaced). So we just join.

                        final_pieces.join(&jd)
                    } else {
                        final_pieces.concat()
                    };

                    if !final_line.is_empty() || !final_pieces.is_empty() {
                        if zero_terminated {
                            out_handle.write_all(final_line.as_bytes()).unwrap();
                            out_handle.write_all(&[0]).unwrap();
                        } else {
                            out_handle.write_all(final_line.as_bytes()).unwrap();
                            out_handle.write_all(b"\n").unwrap();
                        }
                    } else {
                        // Empty field case: output empty line?
                        // For "a::b" -f 2 gives empty field, should output empty line (newline)
                        // So we output line delimiter even if final_line empty, as long as line was processed and not filtered.

                        // Check if we had any resolved (even if empty field)
                        // If split.fields contains empty string at selected position, final_line will be "" but we should output empty line.

                        // We'll output newline.
                        if zero_terminated {
                            out_handle.write_all(&[0]).unwrap();
                        } else {
                            out_handle.write_all(b"\n").unwrap();
                        }
                    }
                }
            }
        }

        if had_error_overall {
            process::exit(1);
        }
        process::exit(0);
    }
}
RS
cargo build --release --offline 2>&1 | tail -n 50
"}

