#[derive(Debug, Clone, Copy, PartialEq)]
enum Mode { Fields, Bytes, Chars, Lines }

#[derive(Debug, Clone, Copy, PartialEq)]
enum TrimType { Left, Right, Both }

#[derive(Debug, Clone)]
enum BoundItem {
    Single { value: i64, fallback: Option<String>, raw: String },
    Range { left: Option<i64>, right: Option<i64>, fallback: Option<String>, raw: String },
}

#[derive(Debug, Clone)]
enum FormatPart { Lit(String), Placeholder(Vec<BoundItem>) }

fn parse_trim_type(s: &str) -> Result<TrimType, String> {
    match s {
        "l" | "L" => Ok(TrimType::Left),
        "r" | "R" => Ok(TrimType::Right),
        "b" | "B" => Ok(TrimType::Both),
        _ => Err(format!("failed to parse '{}': Valid trim values are (l|L)eft, (r|R)ight, (b|B)oth", s)),
    }
}

fn parse_single_token(token: &str, full: &str) -> Result<BoundItem, String> {
    let (main_part, fallback) = if let Some(idx) = token.find('=') {
        (&token[..idx], Some(token[idx+1..].to_string()))
    } else {
        (token, None)
    };
    if main_part.is_empty() {
        return Err(format!("failed to parse '{}': Field format error: empty field", full));
    }
    if main_part.contains(':') {
        let colon = main_part.find(':').unwrap();
        let left_s = &main_part[..colon];
        let right_s = &main_part[colon+1..];
        if left_s.is_empty() && right_s.is_empty() {
            return Err(format!("failed to parse '{}': Field format error, no numbers next to `:`", full));
        }
        let left_opt = if left_s.is_empty() {
            None
        } else {
            match left_s.parse::<i64>() {
                Ok(v) => {
                    if v==0 { return Err(format!("failed to parse '{}': Zero is not a valid field", full)); }
                    Some(v)
                },
                Err(_) => return Err(format!("failed to parse '{}': Not a number `{}`", full, left_s)),
            }
        };
        let right_opt = if right_s.is_empty() {
            None
        } else {
            match right_s.parse::<i64>() {
                Ok(v) => {
                    if v==0 { return Err(format!("failed to parse '{}': Zero is not a valid field", full)); }
                    Some(v)
                },
                Err(_) => return Err(format!("failed to parse '{}': Not a number `{}`", full, right_s)),
            }
        };
        if let (Some(l), Some(r)) = (left_opt, right_opt) {
            if l>0 && r>0 && l>r {
                return Err(format!("failed to parse '{}': Field left value cannot be greater than right value", full));
            }
            if l<0 && r<0 && l>r {
                return Err(format!("failed to parse '{}': Field left value cannot be greater than right value", full));
            }
        }
        Ok(BoundItem::Range { left: left_opt, right: right_opt, fallback, raw: token.to_string() })
    } else {
        match main_part.parse::<i64>() {
            Ok(v) => {
                if v==0 { return Err(format!("failed to parse '{}': Zero is not a valid field", full)); }
                Ok(BoundItem::Single { value: v, fallback, raw: token.to_string() })
            },
            Err(_) => Err(format!("failed to parse '{}': Not a number `{}`", full, main_part)),
        }
    }
}

fn parse_bounds_list(full: &str) -> Result<Vec<BoundItem>, String> {
    if full.is_empty() {
        return Err("failed to parse '': Field format error: empty field".to_string());
    }
    if full.split(',').any(|p| p.is_empty()) {
        return Err(format!("failed to parse '{}': Field format error: empty field", full));
    }
    let mut res = Vec::new();
    for part in full.split(',') {
        res.push(parse_single_token(part, full)?);
    }
    if res.is_empty() {
        panic!("UserBoundsList must contain at least one UserBounds");
    }
    Ok(res)
}

fn parse_bounds_list_with_outer(inner: &str, outer: &str) -> Result<Vec<BoundItem>, String> {
    if inner.is_empty() {
        return Err(format!("failed to parse '{}': Field format error: empty field", outer));
    }
    if inner.split(',').any(|p| p.is_empty()) {
        return Err(format!("failed to parse '{}': Field format error: empty field", outer));
    }
    let mut res = Vec::new();
    for part in inner.split(',') {
        if part.is_empty() {
            return Err(format!("failed to parse '{}': Field format error: empty field", outer));
        }
        res.push(parse_single_token(part, outer)?);
    }
    Ok(res)
}

fn is_format_string(s: &str) -> bool {
    s.contains('{') || s.contains('}')
}

fn parse_format(s: &str) -> Result<Vec<FormatPart>, String> {
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    let mut parts = Vec::new();
    let mut lit = String::new();
    let mut has_ph = false;
    while i < chars.len() {
        if chars[i] == '{' {
            if i+1 < chars.len() && chars[i+1] == '{' {
                lit.push('{');
                i+=2;
            } else {
                if !lit.is_empty() {
                    parts.push(FormatPart::Lit(lit.clone()));
                    lit.clear();
                }
                // find next '}'
                let mut j = i+1;
                let mut close = None;
                while j < chars.len() {
                    if chars[j] == '}' {
                        close = Some(j);
                        break;
                    }
                    j+=1;
                }
                if let Some(cidx) = close {
                    let content: String = chars[i+1..cidx].iter().collect();
                    if content.is_empty() {
                        return Err(format!("failed to parse '{}': Field format error: empty field", s));
                    }
                    let bounds = parse_bounds_list_with_outer(&content, s)?;
                    has_ph = true;
                    parts.push(FormatPart::Placeholder(bounds));
                    i = cidx+1;
                } else {
                    return Err(format!("failed to parse '{}': Field format error: missing closing parenthesis", s));
                }
            }
        } else if chars[i] == '}' {
            if i+1 < chars.len() && chars[i+1] == '}' {
                lit.push('}');
                i+=2;
            } else {
                return Err(format!("failed to parse '{}': Field format error: missing opening parenthesis", s));
            }
        } else {
            lit.push(chars[i]);
            i+=1;
        }
    }
    if !lit.is_empty() {
        parts.push(FormatPart::Lit(lit));
    }
    if !has_ph {
        panic!("UserBoundsList must contain at least one UserBounds");
    }
    Ok(parts)
}

struct DelimInfo {
    is_regex: bool,
    pattern: String,
    regex: Option<Regex>,
}
impl DelimInfo {
    fn new_str(s: String) -> Self { Self { is_regex:false, pattern:s, regex:None } }
    fn new_regex(pat: String) -> Result<Self, String> {
        match Regex::new(&pat) {
            Ok(r) => Ok(Self { is_regex:true, pattern:pat, regex:Some(r)}),
            Err(e) => Err(format!("regex error: {}", e)),
        }
    }
    fn contains_delim(&self, line: &str) -> bool {
        if self.is_regex {
            self.regex.as_ref().unwrap().is_match(line)
        } else {
            if self.pattern.is_empty() { false } else { line.contains(&self.pattern) }
        }
    }
}

#[derive(Clone)]
struct FieldSplit {
    fields: Vec<String>,
    delims: Vec<String>,
    run_counts: Vec<usize>,
}

fn split_fields(line: &str, delim: &DelimInfo, greedy: bool) -> FieldSplit {
    if delim.is_regex {
        let re = delim.regex.as_ref().unwrap();
        let mut matches: Vec<(usize, usize)> = Vec::new();
        for m in re.find_iter(line) {
            matches.push((m.start(), m.end()));
        }
        if matches.is_empty() {
            return FieldSplit { fields: vec![line.to_string()], delims: vec![], run_counts: vec![] };
        }
        if greedy {
            let mut grouped: Vec<(usize, usize, usize)> = Vec::new();
            let mut i=0;
            while i<matches.len() {
                let mut rs = matches[i].0;
                let mut re_end = matches[i].1;
                let mut cnt=1;
                let mut j=i+1;
                while j<matches.len() && matches[j].0==re_end {
                    re_end = matches[j].1;
                    cnt+=1;
                    j+=1;
                }
                grouped.push((rs,re_end,cnt));
                i=j;
            }
            let mut fields = Vec::new();
            let mut delims = Vec::new();
            let mut run_counts = Vec::new();
            let mut last=0;
            for (rs,re,cnt) in grouped {
                fields.push(line[last..rs].to_string());
                delims.push(line[rs..re].to_string());
                run_counts.push(cnt);
                last=re;
            }
            fields.push(line[last..].to_string());
            FieldSplit { fields, delims, run_counts }
        } else {
            let mut fields = Vec::new();
            let mut delims = Vec::new();
            let mut run_counts = Vec::new();
            let mut last=0;
            for (s,e) in matches {
                fields.push(line[last..s].to_string());
                delims.push(line[s..e].to_string());
                run_counts.push(1);
                last=e;
            }
            fields.push(line[last..].to_string());
            FieldSplit { fields, delims, run_counts }
        }
    } else {
        let pat = &delim.pattern;
        if pat.is_empty() {
            return FieldSplit { fields: vec![line.to_string()], delims: vec![], run_counts: vec![] };
        }
        let mut occ: Vec<(usize, usize)> = Vec::new();
        let mut search=0;
        while search <= line.len() {
            if let Some(pos)= line[search..].find(pat) {
                let s=search+pos;
                let e=s+pat.len();
                occ.push((s,e));
                search=e;
            } else { break; }
        }
        if occ.is_empty() {
            return FieldSplit { fields: vec![line.to_string()], delims: vec![], run_counts: vec![] };
        }
        if greedy {
            let mut grouped: Vec<(usize, usize, usize)> = Vec::new();
            let mut i=0;
            while i<occ.len() {
                let mut rs=occ[i].0;
                let mut re=occ[i].1;
                let mut cnt=1;
                let mut j=i+1;
                while j<occ.len() && occ[j].0==re {
                    re=occ[j].1;
                    cnt+=1;
                    j+=1;
                }
                grouped.push((rs,re,cnt));
                i=j;
            }
            let mut fields = Vec::new();
            let mut delims = Vec::new();
            let mut run_counts = Vec::new();
            let mut last=0;
            for (rs,re,cnt) in grouped {
                fields.push(line[last..rs].to_string());
                delims.push(line[rs..re].to_string());
                run_counts.push(cnt);
                last=re;
            }
            fields.push(line[last..].to_string());
            FieldSplit { fields, delims, run_counts }
        } else {
            let mut fields = Vec::new();
            let mut delims = Vec::new();
            let mut run_counts = Vec::new();
            let mut last=0;
            for (s,e) in occ {
                fields.push(line[last..s].to_string());
                delims.push(pat.clone());
                run_counts.push(1);
                last=e;
            }
            fields.push(line[last..].to_string());
            FieldSplit { fields, delims, run_counts }
        }
    }
}

fn trim_line(line: &str, delim: &DelimInfo, trim_type: TrimType) -> String {
    if delim.is_regex {
        let re = delim.regex.as_ref().unwrap();
        let mut s = line.to_string();
        if matches!(trim_type, TrimType::Left | TrimType::Both) {
            loop {
                if let Some(m) = re.find(&s) {
                    if m.start()==0 { s = s[m.end()..].to_string(); } else { break; }
                } else { break; }
            }
        }
        if matches!(trim_type, TrimType::Right | TrimType::Both) {
            loop {
                let mut found: Option<regex::Match> = None;
                for m in re.find_iter(&s) {
                    if m.end()==s.len() { found = Some(m); }
                }
                if let Some(m) = found {
                    s = s[..m.start()].to_string();
                } else { break; }
            }
        }
        s
    } else {
        let pat = &delim.pattern;
        if pat.is_empty() { return line.to_string(); }
        let mut s = line.to_string();
        if matches!(trim_type, TrimType::Left | TrimType::Both) {
            while s.starts_with(pat) { s = s[pat.len()..].to_string(); }
        }
        if matches!(trim_type, TrimType::Right | TrimType::Both) {
            while s.ends_with(pat) { s = s[..s.len()-pat.len()].to_string(); }
        }
        s
    }
}

fn compress_line(line: &str, delim: &DelimInfo) -> String {
    if delim.is_regex {
        let re = delim.regex.as_ref().unwrap();
        let mut result = String::new();
        let mut last=0;
        let matches: Vec<_> = re.find_iter(line).collect();
        let mut i=0;
        while i<matches.len() {
            let run_start = matches[i].start();
            let mut run_end = matches[i].end();
            let mut j=i+1;
            while j<matches.len() && matches[j].start()==run_end {
                run_end = matches[j].end();
                j+=1;
            }
            result.push_str(&line[last..run_start]);
            result.push_str(&line[matches[i].start()..matches[i].end()]);
            last=run_end;
            i=j;
        }
        result.push_str(&line[last..]);
        result
    } else {
        let pat = &delim.pattern;
        if pat.is_empty() { return line.to_string(); }
        let mut occ: Vec<(usize,usize)> = Vec::new();
        let mut search=0;
        while search <= line.len() {
            if let Some(pos)= line[search..].find(pat) {
                let s=search+pos;
                let e=s+pat.len();
                occ.push((s,e));
                search=e;
            } else { break; }
        }
        if occ.is_empty() { return line.to_string(); }
        let mut grouped: Vec<(usize,usize)> = Vec::new();
        let mut i=0;
        while i<occ.len() {
            let mut rs=occ[i].0;
            let mut re=occ[i].1;
            let mut j=i+1;
            while j<occ.len() && occ[j].0==re {
                re=occ[j].1;
                j+=1;
            }
            grouped.push((rs,re));
            i=j;
        }
        let mut res=String::new();
        let mut last=0;
        for (s,e) in grouped {
            res.push_str(&line[last..s]);
            res.push_str(pat);
            last=e;
        }
        res.push_str(&line[last..]);
        res
    }
}

#[derive(Debug, Clone)]
struct Resolved {
    start: usize,
    end: usize,
    fallback: Option<String>,
    raw: String,
    is_range: bool,
}

fn resolve_bounds(fields_len: usize, bounds: &[BoundItem], fallback_oob: &Option<String>) -> Result<Vec<Resolved>, String> {
    let mut out = Vec::new();
    for b in bounds {
        match b {
            BoundItem::Single { value, fallback, raw } => {
                let pos_opt = {
                    let v=*value;
                    if v>0 {
                        if (v as usize) > fields_len { None } else { Some(v as usize) }
                    } else {
                        let p = fields_len as i64 + v +1;
                        if p<1 { None } else { Some(p as usize) }
                    }
                };
                if let Some(p) = pos_opt {
                    out.push(Resolved { start:p, end:p, fallback:fallback.clone(), raw:raw.clone(), is_range:false });
                } else {
                    let fb = fallback.clone().or(fallback_oob.clone());
                    if fb.is_some() {
                        out.push(Resolved { start:0, end:0, fallback:fb, raw:raw.clone(), is_range:false });
                    } else {
                        return Err(format!("Error: Out of bounds: {}", raw));
                    }
                }
            },
            BoundItem::Range { left, right, fallback, raw } => {
                let left_val = left.unwrap_or(1);
                let right_val = right.unwrap_or(fields_len as i64);
                let left_pos_opt = if left.is_none() {
                    Some(1)
                } else {
                    let lv=left_val;
                    if lv>0 {
                        if (lv as usize) > fields_len { None } else { Some(lv as usize) }
                    } else {
                        let p = fields_len as i64 + lv +1;
                        if p<1 { None } else { Some(p as usize) }
                    }
                };
                let right_pos_opt = if right.is_none() {
                    Some(fields_len)
                } else {
                    let rv=right_val;
                    if rv>0 {
                        if (rv as usize) > fields_len {
                            Some(fields_len)
                        } else {
                            Some(rv as usize)
                        }
                    } else {
                        let p = fields_len as i64 + rv +1;
                        if p<1 { Some(1) } else { Some(p as usize) }
                    }
                };
                if left_pos_opt.is_none() {
                    let fb = fallback.clone().or(fallback_oob.clone());
                    if fb.is_some() {
                        out.push(Resolved { start:0, end:0, fallback:fb, raw:raw.clone(), is_range:true });
                        continue;
                    } else {
                        return Err(format!("Error: Out of bounds: {}", left_val));
                    }
                }
                let lpos = left_pos_opt.unwrap();
                let rpos = right_pos_opt.unwrap();
                if lpos > rpos {
                    let fb = fallback.clone().or(fallback_oob.clone());
                    if fb.is_some() {
                        out.push(Resolved { start:0, end:0, fallback:fb, raw:raw.clone(), is_range:true });
                        continue;
                    } else {
                        return Err(format!("Error: Field left value cannot be greater than right value"));
                    }
                }
                out.push(Resolved { start:lpos, end:rpos, fallback:fallback.clone(), raw:raw.clone(), is_range:true });
            }
        }
    }
    Ok(out)
}

fn build_range_slice(split: &FieldSplit, start: usize, end: usize, replace: &Option<String>) -> String {
    if start==0 || end==0 || start>split.fields.len() || end>split.fields.len() || start> end { return String::new(); }
    let mut s = String::new();
    for idx in start..=end {
        s.push_str(&split.fields[idx-1]);
        if idx != end {
            let delim_idx = idx-1;
            if delim_idx < split.delims.len() {
                let cnt = split.run_counts[delim_idx];
                if let Some(rep) = replace {
                    s.push_str(&rep.repeat(cnt));
                } else {
                    s.push_str(&split.delims[delim_idx]);
                }
            }
        }
    }
    s
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() == 1 {
        println!("{}", short_help());
        std::process::exit(0);
    }
    // version/help early
    for a in &args[1..] {
        if a=="-V" || a=="--version" {
            println!("tuc {}", VERSION);
            std::process::exit(0);
        }
        if a=="-h" || a=="--help" {
            println!("{}", long_help());
            std::process::exit(0);
        }
    }

    let mut greedy = false;
    let mut compress = false;
    let mut only_delimited = false;
    let mut zero_terminated = false;
    let mut complement = false;
    let mut join_flag: Option<bool> = None;
    let mut json = false;
    let mut no_mmap = false;

    let mut fields_opt: Option<String> = None;
    let mut bytes_opt: Option<String> = None;
    let mut chars_opt: Option<String> = None;
    let mut lines_opt: Option<String> = None;
    let mut delimiter_opt: Option<String> = None;
    let mut regex_opt: Option<String> = None;
    let mut replace_opt: Option<String> = None;
    let mut trim_opt: Option<String> = None;
    let mut fallback_oob_opt: Option<String> = None;
    let mut fixed_memory_opt: Option<String> = None;
    let mut filepath: Option<String> = None;

    let mut i=1;
    while i < args.len() {
        let arg = &args[i];
        // combined flags like -gs, -jp etc handled
        if arg.starts_with('-') && !arg.starts_with("--") && arg.len()>2 {
            let first = arg.chars().nth(1).unwrap();
            if "fbcldertM".contains(first) {
                // attached value
                let opt_char = first;
                let attached = if arg.len()>2 { &arg[2..] } else { "" };
                let attached = if attached.starts_with('=') { &attached[1..] } else { attached };
                match opt_char {
                    'f' => {
                        let val = if attached.is_empty() {
                            if i+1>=args.len() { eprintln!("the '-f' option doesn't have an associated value"); process::exit(1); }
                            let v = args[i+1].clone(); i+=1; v
                        } else { attached.to_string() };
                        if fields_opt.is_some() {
                            eprintln!("tuc: unexpected arguments: [\"-f\", \"{}\"]\nTry 'tuc --help' for more information.", val);
                            process::exit(1);
                        }
                        fields_opt = Some(val);
                    },
                    'b' => {
                        let val = if attached.is_empty() {
                            if i+1>=args.len() { eprintln!("the '-b' option doesn't have an associated value"); process::exit(1); }
                            let v = args[i+1].clone(); i+=1; v
                        } else { attached.to_string() };
