    while i<args.len() {
        let arg = &args[i];
        if arg.starts_with('-') && !arg.starts_with("--") && arg.len()>2 {
            let first = arg.chars().nth(1).unwrap();
            if "fbcldertM".contains(first) {
                let opt_char = first;
                let attached = if arg.len()>2 { &arg[2..] } else { "" };
                let attached = if attached.starts_with('=') { &attached[1..] } else { attached };
                macro_rules! get_val {
                    ($attached:expr) => {
                        if $attached.is_empty() {
                            if i+1>=args.len() {
                                match opt_char {
                                    'f' => { eprintln!("the '-f' option doesn't have an associated value"); process::exit(1); },
                                    'b' => { eprintln!("the '-b' option doesn't have an associated value"); process::exit(1); },
