                                    't' => { eprintln!("the '-t' option doesn't have an associated value"); process::exit(1); },
                                    'M' => { eprintln!("the '-M' option doesn't have an associated value"); process::exit(1); },
                                    _ => {}
                                }
                            }
                            let v = args[i+1].clone(); i+=1; v
                        } else { $attached.to_string() }
                    }
                }
                match opt_char {
                    'f' => {
                        let val = get_val!(attached);
                        if fields_opt.is_some() { eprintln!("tuc: unexpected arguments: [\"-f\", \"{}\"]\nTry 'tuc --help' for more information.", val); process::exit(1); }
                        fields_opt=Some(val);
                    },
