                        fixed_memory_opt=Some(val);
                    },
                    _ => {}
                }
                i+=1;
                continue;
            } else {
                let flag_chars = &arg[1..];
                if flag_chars.chars().all(|c| "gpszmj".contains(c)) {
                    for ch in flag_chars.chars() {
                        match ch {
                            'g' => { if greedy { eprintln!("tuc: unexpected arguments: [\"-g\"]\nTry 'tuc --help' for more information."); process::exit(1); } greedy=true; },
