                            'z' => { if zero_terminated { eprintln!("tuc: unexpected arguments: [\"-z\"]\nTry 'tuc --help' for more information."); process::exit(1); } zero_terminated=true; },
                            'm' => { if complement { eprintln!("tuc: unexpected arguments: [\"-m\"]\nTry 'tuc --help' for more information."); process::exit(1); } complement=true; },
                            'j' => { if join_flag.is_some() { eprintln!("tuc: unexpected arguments: [\"-j\"]\nTry 'tuc --help' for more information."); process::exit(1); } join_flag=Some(true); },
                            _ => {}
                        }
                    }
                    i+=1;
                    continue;
                }
            }
        }
        match arg.as_str() {
            "-g" | "--greedy-delimiter" => { if greedy { eprintln!("tuc: unexpected arguments: [\"{}\"]\nTry 'tuc --help' for more information.", arg); process::exit(1); } greedy=true; },
            "-p" | "--compress-delimiter" => { if compress { eprintln!("tuc: unexpected arguments: [\"{}\"]\nTry 'tuc --help' for more information.", arg); process::exit(1); } compress=true; },
            "-s" | "--only-delimited" => { if only_delimited { eprintln!("tuc: unexpected arguments: [\"{}\"]\nTry 'tuc --help' for more information.", arg); process::exit(1); } only_delimited=true; },
            "-z" | "--zero-terminated" => { if zero_terminated { eprintln!("tuc: unexpected arguments: [\"{}\"]\nTry 'tuc --help' for more information.", arg); process::exit(1); } zero_terminated=true; },
            "-m" | "--complement" => { if complement { eprintln!("tuc: unexpected arguments: [\"{}\"]\nTry 'tuc --help' for more information.", arg); process::exit(1); } complement=true; },
            "-j" | "--join" => {
                if let Some(v) = join_flag {
                    if v==true { eprintln!("tuc: unexpected arguments: [\"{}\"]\nTry 'tuc --help' for more information.", arg); process::exit(1); }
                    else { eprintln!("tuc: runtime error. It's not possible to use --join and --no-join simultaneously"); process::exit(1); }
                }
                join_flag=Some(true);
            },
            "--no-join" => {
                if let Some(v) = join_flag {
                    if v==false { eprintln!("tuc: unexpected arguments: [\"{}\"]\nTry 'tuc --help' for more information.", arg); process::exit(1); }
                    else { eprintln!("tuc: runtime error. It's not possible to use --join and --no-join simultaneously"); process::exit(1); }
                }
                join_flag=Some(false);
            },
            "--json" => { if json { eprintln!("tuc: unexpected arguments: [\"{}\"]\nTry 'tuc --help' for more information.", arg); process::exit(1); } json=true; },
            "--no-mmap" => { if no_mmap { eprintln!("tuc: unexpected arguments: [\"{}\"]\nTry 'tuc --help' for more information.", arg); process::exit(1); } no_mmap=true; },
            "-f" | "--fields" => {
                if i+1>=args.len() { eprintln!("the '-f' option doesn't have an associated value"); process::exit(1); }
                if fields_opt.is_some() { eprintln!("tuc: unexpected arguments: [\"{}\", \"{}\"]\nTry 'tuc --help' for more information.", arg, args[i+1]); process::exit(1); }
                fields_opt=Some(args[i+1].clone()); i+=1;
