            "-b" | "--bytes" => {
                if i+1>=args.len() { eprintln!("the '-b' option doesn't have an associated value"); process::exit(1); }
                if bytes_opt.is_some() { eprintln!("tuc: unexpected arguments: [\"{}\", \"{}\"]\nTry 'tuc --help' for more information.", arg, args[i+1]); process::exit(1); }
