                if lines_opt.is_some() { eprintln!("tuc: unexpected arguments: [\"{}\", \"{}\"]\nTry 'tuc --help' for more information.", arg, args[i+1]); process::exit(1); }
                lines_opt=Some(args[i+1].clone()); i+=1;
            },
            "-d" | "--delimiter" => {
                if i+1>=args.len() { eprintln!("the '-d' option doesn't have an associated value"); process::exit(1); }
                if delimiter_opt.is_some() || regex_opt.is_some() { eprintln!("tuc: unexpected arguments: [\"{}\", \"{}\"]\nTry 'tuc --help' for more information.", arg, args[i+1]); process::exit(1); }
                delimiter_opt=Some(args[i+1].clone()); i+=1;
