            "-e" | "--regex" => {
                if i+1>=args.len() { eprintln!("the '-e' option doesn't have an associated value"); process::exit(1); }
                if delimiter_opt.is_some() || regex_opt.is_some() { eprintln!("tuc: unexpected arguments: [\"{}\", \"{}\"]\nTry 'tuc --help' for more information.", arg, args[i+1]); process::exit(1); }
                regex_opt=Some(args[i+1].clone()); i+=1;
            },
            "-r" | "--replace-delimiter" => {
