                        process::exit(1);
                    }
                    filepath=Some(arg.clone());
                }
            }
        }
        i+=1;
    }

    let mut mode = Mode::Fields;
    let mut bounds_str_opt: Option<String> = None;
    if fields_opt.is_some() { mode=Mode::Fields; bounds_str_opt=fields_opt.clone(); }
    else if bytes_opt.is_some() { mode=Mode::Bytes; bounds_str_opt=bytes_opt.clone(); }
    else if chars_opt.is_some() { mode=Mode::Chars; bounds_str_opt=chars_opt.clone(); }
    else if lines_opt.is_some() { mode=Mode::Lines; bounds_str_opt=lines_opt.clone(); }
    else { mode=Mode::Fields; bounds_str_opt=Some("1:".to_string()); }

    let delim_info = if let Some(pat) = regex_opt.clone() {
        match DelimInfo::new_regex(pat) {
            Ok(d) => d,
            Err(e) => { eprintln!("regex error: {}", e); process::exit(1); }
