#[derive(Debug, Clone, Copy, PartialEq)]
enum Mode { Fields, Bytes, Chars, Lines }
#[derive(Debug, Clone, Copy, PartialEq)]
enum TrimType { Left, Right, Both }
#[derive(Debug, Clone)]
enum BoundItem {
    Single { value: i64, fallback: Option<String>, raw: String },
    Range { left: Option<i64>, right: Option<i64>, fallback: Option<String>, raw: String },
}
#[derive(Debug, Clone)]
enum FormatPart { Lit(String), Placeholder(Vec<BoundItem>) }

fn parse_trim_type(s: &str) -> Result<TrimType, String> {
    match s {
        "l" | "L" => Ok(TrimType::Left),
        "r" | "R" => Ok(TrimType::Right),
        "b" | "B" => Ok(TrimType::Both),
        _ => Err(format!("failed to parse '{}': Valid trim values are (l|L)eft, (r|R)ight, (b|B)oth", s)),
    }
}
fn parse_single_token(token: &str, full: &str) -> Result<BoundItem, String> {
    let (main_part, fallback) = if let Some(idx) = token.find('=') {
        (&token[..idx], Some(token[idx+1..].to_string()))
    } else {
        (token, None)
    };
    if main_part.is_empty() {
        return Err(format!("failed to parse '{}': Field format error: empty field", full));
    }
    if main_part.contains(':') {
        let colon = main_part.find(':').unwrap();
        let left_s = &main_part[..colon];
        let right_s = &main_part[colon+1..];
        if left_s.is_empty() && right_s.is_empty() {
            return Err(format!("failed to parse '{}': Field format error, no numbers next to `:`", full));
        }
        let left_opt = if left_s.is_empty() { None } else {
            match left_s.parse::<i64>() {
                Ok(v) => { if v==0 { return Err(format!("failed to parse '{}': Zero is not a valid field", full)); } Some(v) },
                Err(_) => return Err(format!("failed to parse '{}': Not a number `{}`", full, left_s)),
            }
        };
        let right_opt = if right_s.is_empty() { None } else {
            match right_s.parse::<i64>() {
                Ok(v) => { if v==0 { return Err(format!("failed to parse '{}': Zero is not a valid field", full)); } Some(v) },
                Err(_) => return Err(format!("failed to parse '{}': Not a number `{}`", full, right_s)),
            }
        };
        if let (Some(l), Some(r)) = (left_opt, right_opt) {
            if l>0 && r>0 && l>r {
                return Err(format!("failed to parse '{}': Field left value cannot be greater than right value", full));
            }
            if l<0 && r<0 && l>r {
                return Err(format!("failed to parse '{}': Field left value cannot be greater than right value", full));
            }
        }
        Ok(BoundItem::Range { left: left_opt, right: right_opt, fallback, raw: token.to_string() })
    } else {
        match main_part.parse::<i64>() {
            Ok(v) => {
                if v==0 { return Err(format!("failed to parse '{}': Zero is not a valid field", full)); }
                Ok(BoundItem::Single { value: v, fallback, raw: token.to_string() })
            },
            Err(_) => Err(format!("failed to parse '{}': Not a number `{}`", full, main_part)),
        }
    }
}
fn parse_bounds_list(full: &str) -> Result<Vec<BoundItem>, String> {
    if full.is_empty() {
        return Err("failed to parse '': Field format error: empty field".to_string());
    }
    if full.split(',').any(|p| p.is_empty()) {
        return Err(format!("failed to parse '{}': Field format error: empty field", full));
    }
    let mut res = Vec::new();
    for part in full.split(',') {
        res.push(parse_single_token(part, full)?);
    }
    if res.is_empty() { panic!("UserBoundsList must contain at least one UserBounds"); }
    Ok(res)
}
fn parse_bounds_list_with_outer(inner: &str, outer: &str) -> Result<Vec<BoundItem>, String> {
    if inner.is_empty() {
        return Err(format!("failed to parse '{}': Field format error: empty field", outer));
    }
    if inner.split(',').any(|p| p.is_empty()) {
        return Err(format!("failed to parse '{}': Field format error: empty field", outer));
    }
    let mut res = Vec::new();
    for part in inner.split(',') {
        res.push(parse_single_token(part, outer)?);
    }
    Ok(res)
}
fn is_format_string(s: &str) -> bool { s.contains('{') || s.contains('}') }
fn parse_format(s: &str) -> Result<Vec<FormatPart>, String> {
    let chars: Vec<char> = s.chars().collect();
    let mut i=0;
    let mut parts=Vec::new();
    let mut lit=String::new();
    let mut has_ph=false;
    while i<chars.len() {
        if chars[i]=='{' {
            if i+1<chars.len() && chars[i+1]=='{' {
                lit.push('{');
                i+=2;
            } else {
                if !lit.is_empty() { parts.push(FormatPart::Lit(lit.clone())); lit.clear(); }
                let mut j=i+1;
                let mut close=None;
                while j<chars.len() {
                    if chars[j]=='}' { close=Some(j); break; }
                    j+=1;
                }
                if let Some(cidx)=close {
                    let content: String = chars[i+1..cidx].iter().collect();
                    if content.is_empty() {
                        return Err(format!("failed to parse '{}': Field format error: empty field", s));
                    }
                    let bounds = parse_bounds_list_with_outer(&content, s)?;
                    has_ph=true;
                    parts.push(FormatPart::Placeholder(bounds));
                    i=cidx+1;
                } else {
                    return Err(format!("failed to parse '{}': Field format error: missing closing parenthesis", s));
                }
            }
        } else if chars[i]=='}' {
            if i+1<chars.len() && chars[i+1]=='}' {
                lit.push('}');
                i+=2;
            } else {
                return Err(format!("failed to parse '{}': Field format error: missing opening parenthesis", s));
            }
        } else {
            lit.push(chars[i]);
            i+=1;
        }
    }
    if !lit.is_empty() { parts.push(FormatPart::Lit(lit)); }
    if !has_ph { panic!("UserBoundsList must contain at least one UserBounds"); }
    Ok(parts)
}
fn json_escape(s: &str) -> String {
    let mut out=String::new();
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\x08' => out.push_str("\\b"),
            '\x0C' => out.push_str("\\f"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c.is_control() => out.push_str(&format!("\\u{:04x}", c as u32)),
            _ => out.push(c),
        }
    }
    out
}
struct DelimInfo {
    is_regex: bool,
    pattern: String,
    regex: Option<Regex>,
}
impl DelimInfo {
    fn new_str(s: String) -> Self { Self { is_regex:false, pattern:s, regex:None } }
    fn new_regex(pat: String) -> Result<Self, String> {
        match Regex::new(&pat) {
            Ok(r) => Ok(Self { is_regex:true, pattern:pat, regex:Some(r)}),
            Err(e) => Err(format!("regex error: {}", e)),
        }
    }
    fn contains_delim(&self, line: &str) -> bool {
        if self.is_regex {
            self.regex.as_ref().unwrap().is_match(line)
        } else {
            if self.pattern.is_empty() { false } else { line.contains(&self.pattern) }
        }
    }
}
#[derive(Clone)]
struct FieldSplit {
    fields: Vec<String>,
    delims: Vec<String>,
    run_counts: Vec<usize>,
}
fn split_fields(line: &str, delim: &DelimInfo, greedy: bool) -> FieldSplit {
    if delim.is_regex {
        let re = delim.regex.as_ref().unwrap();
        let mut matches: Vec<(usize, usize)> = Vec::new();
        for m in re.find_iter(line) { matches.push((m.start(), m.end())); }
        if matches.is_empty() {
            return FieldSplit { fields: vec![line.to_string()], delims: vec![], run_counts: vec![] };
        }
        if greedy {
            let mut grouped: Vec<(usize, usize, usize)> = Vec::new();
            let mut i=0;
            while i<matches.len() {
                let mut rs = matches[i].0;
                let mut re_end = matches[i].1;
                let mut cnt=1;
                let mut j=i+1;
                while j<matches.len() && matches[j].0==re_end {
                    re_end = matches[j].1;
                    cnt+=1;
                    j+=1;
                }
                grouped.push((rs,re_end,cnt));
                i=j;
            }
            let mut fields=Vec::new();
            let mut delims=Vec::new();
            let mut run_counts=Vec::new();
            let mut last=0;
            for (rs,re,cnt) in grouped {
                fields.push(line[last..rs].to_string());
                delims.push(line[rs..re].to_string());
                run_counts.push(cnt);
                last=re;
            }
            fields.push(line[last..].to_string());
            FieldSplit { fields, delims, run_counts }
        } else {
            let mut fields=Vec::new();
            let mut delims=Vec::new();
            let mut run_counts=Vec::new();
            let mut last=0;
            for (s,e) in matches {
                fields.push(line[last..s].to_string());
                delims.push(line[s..e].to_string());
                run_counts.push(1);
                last=e;
            }
            fields.push(line[last..].to_string());
            FieldSplit { fields, delims, run_counts }
