fn trim_line(line: &str, delim: &DelimInfo, trim_type: TrimType) -> String {
    if delim.is_regex {
        let re = delim.regex.as_ref().unwrap();
        let mut s = line.to_string();
        if matches!(trim_type, TrimType::Left | TrimType::Both) {
            loop {
                if let Some(m) = re.find(&s) {
                    if m.start()==0 { s = s[m.end()..].to_string(); } else { break; }
                } else { break; }
            }
        }
        if matches!(trim_type, TrimType::Right | TrimType::Both) {
            loop {
                let mut found: Option<regex::Match> = None;
                for m in re.find_iter(&s) {
                    if m.end()==s.len() { found = Some(m); }
                }
                if let Some(m) = found {
                    s = s[..m.start()].to_string();
                } else { break; }
            }
        }
        s
    } else {
        let pat = &delim.pattern;
        if pat.is_empty() { return line.to_string(); }
        let mut s = line.to_string();
        if matches!(trim_type, TrimType::Left | TrimType::Both) {
            while s.starts_with(pat) { s = s[pat.len()..].to_string(); }
        }
        if matches!(trim_type, TrimType::Right | TrimType::Both) {
            while s.ends_with(pat) { s = s[..s.len()-pat.len()].to_string(); }
        }
        s
    }
}
fn compress_line(line: &str, delim: &DelimInfo) -> String {
    if delim.is_regex {
        let re = delim.regex.as_ref().unwrap();
        let mut result = String::new();
        let mut last=0;
        let matches: Vec<_> = re.find_iter(line).collect();
        let mut i=0;
        while i<matches.len() {
            let run_start = matches[i].start();
            let mut run_end = matches[i].end();
            let mut j=i+1;
            while j<matches.len() && matches[j].start()==run_end {
                run_end = matches[j].end();
                j+=1;
            }
            result.push_str(&line[last..run_start]);
            result.push_str(&line[matches[i].start()..matches[i].end()]);
            last=run_end;
            i=j;
        }
        result.push_str(&line[last..]);
        result
    } else {
        let pat = &delim.pattern;
        if pat.is_empty() { return line.to_string(); }
        let mut occ: Vec<(usize,usize)> = Vec::new();
        let mut search=0;
        while search <= line.len() {
            if let Some(pos)= line[search..].find(pat) {
                let s=search+pos;
                let e=s+pat.len();
                occ.push((s,e));
                search=e;
            } else { break; }
        }
        if occ.is_empty() { return line.to_string(); }
        let mut grouped: Vec<(usize,usize)> = Vec::new();
        let mut i=0;
        while i<occ.len() {
            let mut rs=occ[i].0;
            let mut re=occ[i].1;
            let mut j=i+1;
            while j<occ.len() && occ[j].0==re {
                re=occ[j].1;
                j+=1;
            }
            grouped.push((rs,re));
            i=j;
        }
        let mut res=String::new();
        let mut last=0;
        for (s,e) in grouped {
            res.push_str(&line[last..s]);
            res.push_str(pat);
            last=e;
        }
        res.push_str(&line[last..]);
        res
    }
}
#[derive(Debug, Clone)]
struct Resolved {
    start: usize,
    end: usize,
    fallback: Option<String>,
    raw: String,
    is_range: bool,
}
fn resolve_bounds(fields_len: usize, bounds: &[BoundItem], fallback_oob: &Option<String>) -> Result<Vec<Resolved>, String> {
    let mut out=Vec::new();
    for b in bounds {
        match b {
            BoundItem::Single { value, fallback, raw } => {
                let pos_opt = if *value>0 {
                    if (*value as usize) > fields_len { None } else { Some(*value as usize) }
                } else {
                    let p = fields_len as i64 + *value +1;
                    if p<1 || p> fields_len as i64 { None } else { Some(p as usize) }
                };
                if let Some(p)=pos_opt {
                    out.push(Resolved { start:p, end:p, fallback:fallback.clone(), raw:raw.clone(), is_range:false });
                } else {
                    let fb = fallback.clone().or(fallback_oob.clone());
                    if fb.is_some() {
                        out.push(Resolved { start:0, end:0, fallback:fb, raw:raw.clone(), is_range:false });
                    } else {
                        return Err(format!("Error: Out of bounds: {}", raw));
                    }
                }
            },
            BoundItem::Range { left, right, fallback, raw } => {
                let left_val = left.unwrap_or(1);
                let right_val = right.unwrap_or(fields_len as i64);
                let left_pos_opt = if left.is_none() { Some(1) } else {
                    let lv=left_val;
                    if lv>0 {
                        if (lv as usize) > fields_len { None } else { Some(lv as usize) }
                    } else {
                        let p = fields_len as i64 + lv +1;
                        if p<1 { None } else { Some(p as usize) }
                    }
                };
                let right_pos_opt = if right.is_none() { Some(fields_len) } else {
                    let rv=right_val;
                    if rv>0 {
                        if (rv as usize) > fields_len { Some(fields_len) } else { Some(rv as usize) }
                    } else {
                        let p = fields_len as i64 + rv +1;
                        if p<1 { Some(1) } else { Some(p as usize) }
                    }
                };
                if left_pos_opt.is_none() {
                    let fb = fallback.clone().or(fallback_oob.clone());
                    if fb.is_some() {
                        out.push(Resolved { start:0, end:0, fallback:fb, raw:raw.clone(), is_range:true });
                        continue;
                    } else {
                        return Err(format!("Error: Out of bounds: {}", left_val));
                    }
                }
                let lpos = left_pos_opt.unwrap();
                let rpos = right_pos_opt.unwrap();
                if lpos > rpos {
                    let fb = fallback.clone().or(fallback_oob.clone());
                    if fb.is_some() {
                        out.push(Resolved { start:0, end:0, fallback:fb, raw:raw.clone(), is_range:true });
                        continue;
                    } else {
                        return Err(format!("Error: Field left value cannot be greater than right value"));
                    }
                }
                out.push(Resolved { start:lpos, end:rpos, fallback:fallback.clone(), raw:raw.clone(), is_range:true });
            }
        }
    }
    Ok(out)
}
fn build_range_slice(split: &FieldSplit, start: usize, end: usize, replace: &Option<String>) -> String {
    if start==0 || end==0 || start>split.fields.len() || end>split.fields.len() || start> end { return String::new(); }
    let mut s=String::new();
    for idx in start..=end {
        s.push_str(&split.fields[idx-1]);
        if idx != end {
            let delim_idx = idx-1;
            if delim_idx < split.delims.len() {
                let cnt = split.run_counts[delim_idx];
                if let Some(rep) = replace {
                    s.push_str(&rep.repeat(cnt));
                } else {
                    s.push_str(&split.delims[delim_idx]);
                }
            }
        }
    }
    s
}
