    if let Some(false)=join_flag {
        if replace_opt.is_some() {
            eprintln!("tuc: runtime error. You can't pass --no-join when using --replace, which implies --join");
            process::exit(1);
        }
    }
    if delim_info.is_regex {
        if let Some(true)=join_flag {
            if replace_opt.is_none() {
                eprintln!("tuc: runtime error. Cannot use --regex and --join without --replace-delimiter");
                process::exit(1);
            }
        }
    }
    if json {
        if mode==Mode::Bytes || mode==Mode::Lines {
            eprintln!("tuc: runtime error. --json support is available only for --fields and --characters");
            process::exit(1);
        }
        if replace_opt.is_some() {
            eprintln!("tuc: runtime error. The use of --replace with --json is not supported");
            process::exit(1);
        }
        if let Some(false)=join_flag {
            eprintln!("tuc: runtime error. Using both --json and --no-join is not permitted");
            process::exit(1);
        }
    }
    if compress {
        if mode==Mode::Bytes || mode==Mode::Chars {
            eprintln!("tuc: runtime error. Delimiters can be compressed only with --fields and --lines");
            process::exit(1);
        }
    }

    if let Some(_) = fixed_memory_opt.clone() {
        if !delim_info.is_regex && delim_info.pattern.len()!=1 {
            eprintln!("tuc: runtime error. Delimiter must be 1 byte wide for FastOpt");
            process::exit(1);
        }
        if greedy || compress || only_delimited || trim_type.is_some() || complement || json || mode!=Mode::Fields {
            eprintln!("tuc: runtime error. StreamOpt supports solely forward fields, join and single-character delimiters");
            process::exit(1);
        }
        if let Some(false)=join_flag {
            eprintln!("tuc: runtime error. It's not possible to use --join and --no-join simultaneously");
            process::exit(1);
        }
        let bstr = bounds_str_opt.clone().unwrap();
        if is_format_string(&bstr) {
            eprintln!("tuc: runtime error. StreamOpt supports solely forward fields, join and single-character delimiters");
            process::exit(1);
        }
        let parsed = match parse_bounds_list(&bstr) {
            Ok(v) => v,
            Err(e) => { eprintln!("{}", e); process::exit(1); }
        };
        let mut prev_end: Option<i64>=None;
        let mut forward=true;
        for item in &parsed {
            match item {
                BoundItem::Single { value, .. } => {
                    if *value<0 { forward=false; break; }
                    if let Some(pe)=prev_end {
                        if *value <= pe { forward=false; break; }
                    }
                    prev_end=Some(*value);
                },
                BoundItem::Range { left, right, .. } => {
                    let lv = left.unwrap_or(1);
                    let rv = right.unwrap_or(i64::MAX);
                    if lv<0 { forward=false; break; }
                    if right.is_some() && rv<0 { forward=false; break; }
                    if let (Some(l), Some(r)) = (left, right) {
                        if l>r { forward=false; break; }
                    }
                    if let Some(pe)=prev_end {
                        if lv <= pe { forward=false; break; }
                    }
                    if right.is_some() { prev_end=Some(rv); } else { prev_end=Some(i64::MAX); }
                }
            }
        }
        for (idx, item) in parsed.iter().enumerate() {
            if let BoundItem::Range { right:None, .. } = item {
                if idx != parsed.len()-1 { forward=false; break; }
            }
        }
        if !forward {
            eprintln!("tuc: runtime error. Bounds cannot be converted to ForwardBounds");
            process::exit(1);
        }
    }

    let input_bytes: Vec<u8> = if let Some(path)=filepath.clone() {
        match fs::read(&path) {
            Ok(d) => d,
            Err(e) => { eprintln!("tuc: cannot open file {}: {}", path, e); process::exit(1); }
        }
    } else {
        let mut buf=Vec::new();
        io::stdin().read_to_end(&mut buf).unwrap();
        buf
    };

    let line_delim = if zero_terminated { 0u8 } else { b'\n' };

    let stdout = io::stdout();
    let mut out_handle = stdout.lock();

    if fixed_memory_opt.is_some() {
        let data_str = String::from_utf8_lossy(&input_bytes);
        let lines: Vec<&str> = if zero_terminated { data_str.split('\0').collect() } else { data_str.split('\n').collect() };
        let bstr = bounds_str_opt.clone().unwrap();
        let bounds_list = match parse_bounds_list(&bstr) {
            Ok(v) => v,
            Err(e) => { eprintln!("{}", e); process::exit(1); }
        };
        for (line_idx, line) in lines.iter().enumerate() {
            let is_last = line_idx == lines.len()-1;
            let is_trailing_empty = if !zero_terminated {
                is_last && line.is_empty() && input_bytes.ends_with(&[line_delim])
            } else {
                is_last && line.is_empty() && input_bytes.ends_with(&[0])
            };
            if is_trailing_empty { continue; }
            let split = split_fields(line, &delim_info, false);
            let mut resolved: Vec<Resolved> = Vec::new();
            let mut err_msg: Option<String> = None;
            for item in &bounds_list {
                match item {
                    BoundItem::Single { value, fallback, raw } => {
                        let pos_opt = if *value>0 {
                            if (*value as usize) > split.fields.len() { None } else { Some(*value as usize) }
                        } else { None };
                        if let Some(p)=pos_opt {
                            resolved.push(Resolved { start:p, end:p, fallback:fallback.clone(), raw:raw.clone(), is_range:false });
                        } else {
                            let fb = fallback.clone().or(fallback_oob_opt.clone());
                            if fb.is_some() {
                                resolved.push(Resolved { start:0, end:0, fallback:fb, raw:raw.clone(), is_range:false });
                            } else {
                                err_msg = Some(format!("Error: Out of bounds: {}", raw));
                                break;
                            }
                        }
                    },
                    BoundItem::Range { left, right, fallback, raw } => {
                        let left_val = left.unwrap_or(1);
                        let right_val = right.unwrap_or(split.fields.len() as i64);
                        let left_pos_opt = if left.is_none() { Some(1) } else {
                            let lv=left_val;
                            if lv>0 {
                                if (lv as usize) > split.fields.len() { None } else { Some(lv as usize) }
                            } else { None }
                        };
                        let right_pos_opt = if right.is_none() { Some(split.fields.len()) } else {
                            let rv=right_val;
                            if rv>0 {
                                if (rv as usize) > split.fields.len() { None } else { Some(rv as usize) }
                            } else { None }
                        };
                        if left_pos_opt.is_none() {
                            let fb = fallback.clone().or(fallback_oob_opt.clone());
                            if fb.is_some() {
                                resolved.push(Resolved { start:0, end:0, fallback:fb, raw:raw.clone(), is_range:true });
                                continue;
                            } else {
                                err_msg = Some(format!("Error: Out of bounds: {}", left_val));
                                break;
                            }
                        }
                        if right_pos_opt.is_none() {
                            let lpos = left_pos_opt.unwrap();
                            if lpos <= split.fields.len() {
                                resolved.push(Resolved { start:lpos, end:split.fields.len(), fallback:fallback.clone(), raw:raw.clone(), is_range:true });
                            }
                            err_msg = Some(format!("Error: Out of bounds: {}", left_val));
                            break;
                        }
                        let lpos = left_pos_opt.unwrap();
                        let rpos = right_pos_opt.unwrap();
                        if lpos > rpos {
                            err_msg = Some(format!("Error: Field left value cannot be greater than right value"));
                            break;
                        }
                        resolved.push(Resolved { start:lpos, end:rpos, fallback:fallback.clone(), raw:raw.clone(), is_range:true });
                    }
                }
            }
            let mut line_out = String::new();
            if join_flag==Some(true) || replace_opt.is_some() {
                let jdelim = replace_opt.clone().unwrap_or(delim_info.pattern.clone());
                let mut first=true;
                for res in &resolved {
                    if res.start==0 {
                        let fb = res.fallback.clone().unwrap();
                        if first {
                            line_out.push_str(&fb);
                            first=false;
                        } else {
                            line_out.push_str(&jdelim);
                            line_out.push_str(&fb);
                        }
                    } else if res.is_range {
                        let slice = build_range_slice(&split, res.start, res.end, &replace_opt);
                        if first {
                            if res.start==1 { line_out.push_str(&slice); } else { line_out.push_str(&jdelim); line_out.push_str(&slice); }
                            first=false;
                        } else {
                            line_out.push_str(&jdelim);
                            line_out.push_str(&slice);
                        }
                    } else {
                        let fv = split.fields[res.start-1].clone();
                        if first {
                            if res.start==1 { line_out.push_str(&fv); } else { line_out.push_str(&jdelim); line_out.push_str(&fv); }
                            first=false;
                        } else {
                            line_out.push_str(&jdelim);
                            line_out.push_str(&fv);
                        }
                    }
                }
            } else {
                for res in &resolved {
                    if res.start==0 {
                        line_out.push_str(&res.fallback.clone().unwrap());
                    } else if res.is_range {
                        line_out.push_str(&build_range_slice(&split, res.start, res.end, &replace_opt));
                    } else {
                        line_out.push_str(&split.fields[res.start-1]);
                    }
                }
            }
            if !line_out.is_empty() || !resolved.is_empty() {
                if zero_terminated {
                    out_handle.write_all(line_out.as_bytes()).unwrap();
                    out_handle.write_all(&[0]).unwrap();
                } else {
                    out_handle.write_all(line_out.as_bytes()).unwrap();
                    out_handle.write_all(b"\n").unwrap();
                }
            }
            if let Some(em) = err_msg {
                eprintln!("{}", em);
                std::process::exit(1);
            }
        }
        std::process::exit(0);
    }

    if mode == Mode::Bytes {
        let total_len = input_bytes.len();
        let bstr = bounds_str_opt.clone().unwrap();
        let bounds_list = match parse_bounds_list(&bstr) {
            Ok(v) => v,
            Err(e) => { eprintln!("{}", e); process::exit(1); }
        };
        if complement {
            let mut sel_set = HashSet::new();
            let mut had_err=false;
            let mut err_msg: Option<String>=None;
            for item in &bounds_list {
                match item {
                    BoundItem::Single { value, raw, .. } => {
                        let pos = if *value>0 { *value as usize } else {
                            let p = total_len as i64 + *value +1;
                            if p<1 || p> total_len as i64 { 0 } else { p as usize }
                        };
                        if pos==0 || pos>total_len {
                            err_msg=Some(format!("Error: Out of bounds: {}", raw));
                            had_err=true;
                            break;
                        } else { sel_set.insert(pos); }
                    },
                    BoundItem::Range { left, right, raw:_, .. } => {
                        let left_val = left.unwrap_or(1);
                        let right_val = right.unwrap_or(total_len as i64);
                        let left_pos = if left.is_none() { 1 } else {
                            let lv=left_val;
                            if lv>0 {
                                if (lv as usize) > total_len { 0 } else { lv as usize }
                            } else {
                                let p = total_len as i64 + lv +1;
                                if p<1 { 0 } else { p as usize }
                            }
                        };
                        let right_pos = if right.is_none() { total_len } else {
                            let rv=right_val;
                            if rv>0 {
                                if (rv as usize) > total_len { total_len } else { rv as usize }
                            } else {
                                let p = total_len as i64 + rv +1;
                                if p<1 { 1 } else { p as usize }
                            }
                        };
                        if left_pos==0 {
                            err_msg=Some(format!("Error: Out of bounds: {}", left.unwrap_or(1)));
                            had_err=true;
                            break;
                        }
                        if left_pos > right_pos {
                            err_msg=Some(format!("Error: Field left value cannot be greater than right value"));
                            had_err=true;
                            break;
                        }
                        for p in left_pos..=right_pos { sel_set.insert(p); }
                    }
                }
            }
            if had_err { eprintln!("{}", err_msg.unwrap()); process::exit(1); }
            let mut comp: Vec<usize>=Vec::new();
            for idx in 1..=total_len { if !sel_set.contains(&idx) { comp.push(idx); } }
            if comp.is_empty() { eprintln!("Error: the complement is empty"); process::exit(1); }
            let mut out=Vec::new();
            for p in comp { out.push(input_bytes[p-1]); }
            out_handle.write_all(&out).unwrap();
            process::exit(0);
        }
        let mut out=Vec::new();
        let mut err_msg: Option<String>=None;
        for item in &bounds_list {
            match item {
                BoundItem::Single { value, raw, .. } => {
                    let pos = if *value>0 { *value as usize } else {
                        let p = total_len as i64 + *value +1;
                        if p<1 || p> total_len as i64 { 0 } else { p as usize }
                    };
                    if pos==0 || pos>total_len {
                        err_msg=Some(format!("Error: Out of bounds: {}", raw));
                        break;
                    } else { out.push(input_bytes[pos-1]); }
                },
                BoundItem::Range { left, right, .. } => {
                    let left_val = left.unwrap_or(1);
                    let right_val = right.unwrap_or(total_len as i64);
                    let left_pos = if left.is_none() { 1 } else {
                        let lv=left_val;
                        if lv>0 {
                            if (lv as usize) > total_len { 0 } else { lv as usize }
                        } else {
                            let p = total_len as i64 + lv +1;
                            if p<1 { 0 } else { p as usize }
                        }
                    };
                    let right_pos = if right.is_none() { total_len } else {
                        let rv=right_val;
                        if rv>0 {
                            if (rv as usize) > total_len { total_len } else { rv as usize }
                        } else {
                            let p = total_len as i64 + rv +1;
                            if p<1 { 1 } else { p as usize }
                        }
                    };
                    if left_pos==0 { err_msg=Some(format!("Error: Out of bounds: {}", left.unwrap_or(1))); break; }
                    if left_pos > right_pos { err_msg=Some(format!("Error: Field left value cannot be greater than right value")); break; }
                    for p in left_pos..=right_pos { out.push(input_bytes[p-1]); }
                }
            }
        }
        if !out.is_empty() { out_handle.write_all(&out).unwrap(); }
        if let Some(em)=err_msg { eprintln!("{}", em); process::exit(1); }
        process::exit(0);
    }

    let data_str = String::from_utf8_lossy(&input_bytes);
    let lines_input: Vec<String> = if zero_terminated {
        data_str.split('\0').map(|s| s.to_string()).collect()
    } else {
        data_str.split('\n').map(|s| s.to_string()).collect()
    };
    let total_lines_for_bounds = {
        let mut cnt = lines_input.len();
        if !zero_terminated {
            if input_bytes.ends_with(&[line_delim]) && cnt>0 && lines_input[cnt-1].is_empty() { cnt-=1; }
        } else {
            if input_bytes.ends_with(&[0]) && cnt>0 && lines_input[cnt-1].is_empty() { cnt-=1; }
        }
        cnt
    };

    // Lines mode handling (non fixed-memory)
    if mode == Mode::Lines {
        let bstr = bounds_str_opt.clone().unwrap();
        let is_fmt_lines = is_format_string(&bstr);
        if is_fmt_lines { panic!("We didn't use an extract function that counted the number of fields"); }
        let bounds_list = match parse_bounds_list(&bstr) {
            Ok(v) => v,
            Err(e) => { eprintln!("{}", e); process::exit(1); }
        };
        // Check if need whole (complement or compress)
        let need_whole = complement || compress;
        let mut _ordered = true;
        if !need_whole {
            let mut prev: Option<i64>=None;
            for item in &bounds_list {
                match item {
                    BoundItem::Single { value, .. } => {
                        if *value<0 { _ordered=false; break; }
                        if let Some(p)=prev { if *value < p { _ordered=false; break; } }
                        prev=Some(*value);
                    },
                    BoundItem::Range { left, right, .. } => {
                        let lv = left.unwrap_or(1);
                        let rv = right.unwrap_or(total_lines_for_bounds as i64);
                        if lv<0 || rv<0 { _ordered=false; break; }
                        if let Some(p)=prev { if lv < p { _ordered=false; break; } }
                        prev=Some(rv);
                    }
                }
            }
        }

        // For simplicity process whole file for lines

        let mut resolved: Vec<Resolved> = Vec::new();
        let mut err_msg: Option<String>=None;

        for item in &bounds_list {
            match item {
                BoundItem::Single { value, raw, .. } => {
                    let pos_opt = if *value>0 {
                        if (*value as usize) > total_lines_for_bounds { None } else { Some(*value as usize) }
                    } else {
                        let p = total_lines_for_bounds as i64 + *value +1;
                        if p<1 || p> total_lines_for_bounds as i64 { None } else { Some(p as usize) }
                    };
                    if let Some(p)=pos_opt {
                        resolved.push(Resolved { start:p, end:p, fallback:None, raw:raw.clone(), is_range:false });
                    } else {
                        err_msg=Some(format!("Error: Out of bounds: {}", raw));
                        break;
                    }
                },
                BoundItem::Range { left, right, raw, .. } => {
                    let left_val = left.unwrap_or(1);
                    let right_val = right.unwrap_or(total_lines_for_bounds as i64);
                    let left_pos_opt = if left.is_none() { Some(1) } else {
                        let lv=left_val;
                        if lv>0 {
                            if (lv as usize) > total_lines_for_bounds { None } else { Some(lv as usize) }
                        } else {
                            let p = total_lines_for_bounds as i64 + lv +1;
                            if p<1 { None } else { Some(p as usize) }
                        }
                    };
                    let right_pos_opt = if right.is_none() { Some(total_lines_for_bounds) } else {
                        let rv=right_val;
                        if rv>0 {
                            if (rv as usize) > total_lines_for_bounds { None } else { Some(rv as usize) }
                        } else {
                            let p = total_lines_for_bounds as i64 + rv +1;
                            if p<1 { Some(1) } else { Some(p as usize) }
                        }
                    };
                    if left_pos_opt.is_none() {
                        err_msg=Some(format!("Error: Out of bounds: {}", left_val));
                        break;
                    }
                    if right_pos_opt.is_none() {
                        // right OOB for lines: output clamped + error full range
                        let lpos = left_pos_opt.unwrap();
                        resolved.push(Resolved { start:lpos, end:total_lines_for_bounds, fallback:None, raw:raw.clone(), is_range:true });
                        err_msg=Some(format!("Error: Out of bounds: {}", raw));
                        break;
                    }
                    let lpos=left_pos_opt.unwrap();
                    let rpos=right_pos_opt.unwrap();
                    if lpos>rpos {
                        err_msg=Some(format!("Error: Field left value cannot be greater than right value"));
                        break;
                    }
                    resolved.push(Resolved { start:lpos, end:rpos, fallback:None, raw:raw.clone(), is_range:true });
                }
            }
        }

        if complement {
            panic!("We didn't use an extract function that counted the number of fields");
        }

        let mut out_lines: Vec<String> = Vec::new();
        for res in &resolved {
            for p in res.start..=res.end {
                if p<= lines_input.len() {
                    out_lines.push(lines_input[p-1].clone());
                }
            }
        }

        if join_flag==Some(false) {
            let merged = out_lines.concat();
            if zero_terminated {
                out_handle.write_all(merged.as_bytes()).unwrap();
                out_handle.write_all(&[0]).unwrap();
            } else {
                out_handle.write_all(merged.as_bytes()).unwrap();
                out_handle.write_all(b"\n").unwrap();
            }
        } else {
            for l in &out_lines {
                if zero_terminated {
                    out_handle.write_all(l.as_bytes()).unwrap();
                    out_handle.write_all(&[0]).unwrap();
                } else {
                    out_handle.write_all(l.as_bytes()).unwrap();
                    out_handle.write_all(b"\n").unwrap();
                }
            }
        }
        if let Some(em)=err_msg { eprintln!("{}", em); process::exit(1); }
        process::exit(0);
    }

    // Fields and Chars

    let bstr = bounds_str_opt.clone().unwrap();
    let is_fmt = is_format_string(&bstr);
    let format_parts_opt: Option<Vec<FormatPart>> = if is_fmt {
        match parse_format(&bstr) {
            Ok(v) => Some(v),
            Err(e) => { eprintln!("{}", e); process::exit(1); }
        }
    } else { None };

    let bounds_list: Vec<BoundItem> = if !is_fmt {
        match parse_bounds_list(&bstr) {
            Ok(v) => v,
            Err(e) => {
                if e.contains("UserBoundsList") { panic!("{}", e); }
                eprintln!("{}", e); process::exit(1);
            }
        }
    } else { Vec::new() };

    if is_fmt && json {
        if let Some(ref parts) = format_parts_opt {
            if parts.iter().any(|p| matches!(p, FormatPart::Lit(l) if !l.is_empty())) {
                eprintln!("tuc: runtime error. Cannot format fields when using --json");
                process::exit(1);
            }
        }
    }

    let mut overall_error=false;

    let lines_to_process: Vec<String> = {
        let mut v=Vec::new();
        for (idx, line) in lines_input.iter().enumerate() {
            let is_last = idx==lines_input.len()-1;
            let is_trailing = if !zero_terminated {
                is_last && line.is_empty() && input_bytes.ends_with(&[line_delim])
            } else {
                is_last && line.is_empty() && input_bytes.ends_with(&[0])
            };
            if is_trailing { continue; }
            v.push(line.clone());
        }
        v
    };

    if mode==Mode::Chars {
        for line_content in &lines_to_process {
            let mut cur = line_content.clone();
            if let Some(tt)=trim_type { cur = trim_line(&cur, &delim_info, tt); }
            if compress { cur = compress_line(&cur, &delim_info); }
            let chars_vec: Vec<char> = cur.chars().collect();
            let n = chars_vec.len();
            if is_fmt {
                let fmt_parts = format_parts_opt.as_ref().unwrap();
                let mut ph_exps: Vec<String> = Vec::new();
                let mut had_err=false;
                let mut err_msg: Option<String>=None;
                for part in fmt_parts {
                    if let FormatPart::Placeholder(bnds) = part {
                        let resolved = match resolve_bounds(n, bnds, &fallback_oob_opt) {
                            Ok(v) => v,
                            Err(e) => { had_err=true; err_msg=Some(e); break; }
                        };
                        let final_res = if complement {
                            let mut set=HashSet::new();
                            for r in &resolved { if r.start!=0 { for p in r.start..=r.end { set.insert(p); } } }
                            let mut comp_res=Vec::new();
                            for idx in 1..=n { if !set.contains(&idx) { comp_res.push(Resolved { start:idx, end:idx, fallback:None, raw:"".to_string(), is_range:false }); } }
                            if comp_res.is_empty() { had_err=true; err_msg=Some("Error: the complement is empty".to_string()); break; }
                            comp_res
                        } else { resolved };
                        let mut pieces=Vec::new();
                        for res in &final_res {
                            if res.start==0 {
                                pieces.push(res.fallback.clone().unwrap());
                            } else if res.is_range {
                                let slice: String = chars_vec[res.start-1..res.end].iter().collect();
                                pieces.push(slice);
                            } else {
                                pieces.push(chars_vec[res.start-1].to_string());
                            }
                        }
                        let ph_str = if join_flag==Some(true) || replace_opt.is_some() {
                            let jd = replace_opt.clone().unwrap_or("".to_string());
                            pieces.join(&jd)
                        } else {
                            pieces.concat()
                        };
                        ph_exps.push(ph_str);
                    }
                }
                if had_err { if let Some(em)=err_msg { eprintln!("{}", em); } overall_error=true; continue; }
                let ph_positions: Vec<usize> = fmt_parts.iter().enumerate().filter(|(_,p)| matches!(p, FormatPart::Placeholder(_))).map(|(i,_)| i).collect();
                let mut final_out=String::new();
                let mut ph_idx=0;
                let mut last_was_ph=false;
                for (idx, part) in fmt_parts.iter().enumerate() {
                    match part {
                        FormatPart::Lit(l) => {
                            let is_between = {
                                let prev = ph_positions.iter().filter(|&&p| p < idx).last();
                                let next = ph_positions.iter().find(|&&p| p > idx);
                                prev.is_some() && next.is_some()
                            };
                            if join_flag==Some(true) && is_between {
                                let jd = replace_opt.clone().unwrap_or("".to_string());
                                final_out.push_str(&jd);
                                final_out.push_str(l);
                            } else {
                                final_out.push_str(l);
                            }
                            last_was_ph=false;
                        },
                        FormatPart::Placeholder(_) => {
                            if last_was_ph && join_flag==Some(true) {
                                let jd = replace_opt.clone().unwrap_or("".to_string());
                                final_out.push_str(&jd);
                            }
                            final_out.push_str(&ph_exps[ph_idx]);
                            ph_idx+=1;
                            last_was_ph=true;
                        }
                    }
                }
                if zero_terminated {
                    out_handle.write_all(final_out.as_bytes()).unwrap();
                    out_handle.write_all(&[0]).unwrap();
                } else {
                    out_handle.write_all(final_out.as_bytes()).unwrap();
                    out_handle.write_all(b"\n").unwrap();
                }
            } else {
                let mut out_pieces: Vec<String> = Vec::new();
                let mut had_err=false;
                let mut err_local: Option<String>=None;
                for bitem in &bounds_list {
                    match bitem {
                        BoundItem::Single { value, fallback, raw } => {
                            let pos_opt = if *value>0 {
                                if (*value as usize) > n { None } else { Some(*value as usize) }
                            } else {
                                let p = n as i64 + *value +1;
                                if p<1 || p> n as i64 { None } else { Some(p as usize) }
                            };
                            if let Some(p)=pos_opt {
                                out_pieces.push(chars_vec[p-1].to_string());
                            } else {
                                let fb = fallback.clone().or(fallback_oob_opt.clone());
                                if let Some(fb_str)=fb { out_pieces.push(fb_str); } else { err_local=Some(format!("Error: Out of bounds: {}", raw)); had_err=true; break; }
                            }
                        },
                        BoundItem::Range { left, right, fallback, raw } => {
                            let left_val = left.unwrap_or(1);
                            let right_val = right.unwrap_or(n as i64);
                            let left_pos_opt = if left.is_none() { Some(1) } else {
                                let lv=left_val;
                                if lv>0 {
                                    if (lv as usize) > n { None } else { Some(lv as usize) }
                                } else {
                                    let p = n as i64 + lv +1;
                                    if p<1 { None } else { Some(p as usize) }
                                }
                            };
                            let right_pos_opt = if right.is_none() { Some(n) } else {
                                let rv=right_val;
                                if rv>0 {
                                    if (rv as usize) > n { Some(n) } else { Some(rv as usize) }
                                } else {
                                    let p = n as i64 + rv +1;
                                    if p<1 { Some(1) } else { Some(p as usize) }
                                }
                            };
                            if left_pos_opt.is_none() {
                                let fb=fallback.clone().or(fallback_oob_opt.clone());
                                if fb.is_some() { out_pieces.push(fb.unwrap()); } else { err_local=Some(format!("Error: Out of bounds: {}", left_val)); had_err=true; break; }
                            } else {
                                let lpos=left_pos_opt.unwrap();
                                let rpos=right_pos_opt.unwrap();
                                if lpos>rpos {
                                    let fb=fallback.clone().or(fallback_oob_opt.clone());
                                    if fb.is_some() { out_pieces.push(fb.unwrap()); } else { err_local=Some(format!("Error: Field left value cannot be greater than right value")); had_err=true; break; }
                                } else {
                                    let slice: String = chars_vec[lpos-1..rpos].iter().collect();
                                    out_pieces.push(slice);
                                }
                            }
                        }
                    }
                }
                if had_err { eprintln!("{}", err_local.unwrap()); overall_error=true; continue; }
                let final_pieces = if complement {
                    let resolved = resolve_bounds(n, &bounds_list, &fallback_oob_opt).unwrap();
                    let mut set=HashSet::new();
                    for r in &resolved { if r.start!=0 { for p in r.start..=r.end { set.insert(p); } } }
                    let mut comp_chars=Vec::new();
                    for idx in 1..=n { if !set.contains(&idx) { comp_chars.push(chars_vec[idx-1]); } }
                    if comp_chars.is_empty() { eprintln!("Error: the complement is empty"); overall_error=true; continue; }
                    let s: String = comp_chars.into_iter().collect();
                    vec![s]
                } else { out_pieces };
                if json {
                    let mut elems=Vec::new();
                    for res in resolve_bounds(n, &bounds_list, &fallback_oob_opt).unwrap() {
                        if res.start==0 { elems.push(res.fallback.clone().unwrap()); }
                        else if res.is_range { for p in res.start..=res.end { elems.push(chars_vec[p-1].to_string()); } }
                        else { elems.push(chars_vec[res.start-1].to_string()); }
                    }
                    let json_str = format!("[{}]", elems.iter().map(|e| format!("\"{}\"", json_escape(e))).collect::<Vec<_>>().join(","));
                    if zero_terminated {
                        out_handle.write_all(json_str.as_bytes()).unwrap();
                        out_handle.write_all(&[0]).unwrap();
                    } else {
                        out_handle.write_all(json_str.as_bytes()).unwrap();
                        out_handle.write_all(b"\n").unwrap();
                    }
                } else {
                    let final_line = final_pieces.concat();
                    if zero_terminated {
                        out_handle.write_all(final_line.as_bytes()).unwrap();
                        out_handle.write_all(&[0]).unwrap();
                    } else {
                        out_handle.write_all(final_line.as_bytes()).unwrap();
                        out_handle.write_all(b"\n").unwrap();
                    }
                }
            }
        }
        if overall_error { process::exit(1); }
        process::exit(0);
    }

    // Fields mode
    for line_content in &lines_to_process {
        let mut cur = line_content.clone();
        if let Some(tt)=trim_type { cur = trim_line(&cur, &delim_info, tt); }
        let mut cur_after_compress = cur.clone();
        if compress { cur_after_compress = compress_line(&cur, &delim_info); }
        if only_delimited {
            let check = if compress { &cur_after_compress } else { &cur };
            if !delim_info.contains_delim(check) { continue; }
        }
        let split = if compress {
            split_fields(&cur_after_compress, &delim_info, false)
        } else if greedy {
            split_fields(&cur, &delim_info, true)
        } else {
            split_fields(&cur, &delim_info, false)
        };

        if is_fmt {
            let fmt_parts = format_parts_opt.as_ref().unwrap();
            let mut ph_exps: Vec<String> = Vec::new();
            let mut had_err=false;
            let mut err_msg: Option<String>=None;
            for part in fmt_parts {
                if let FormatPart::Placeholder(bnds) = part {
                    let resolved = match resolve_bounds(split.fields.len(), bnds, &fallback_oob_opt) {
                        Ok(v) => v,
                        Err(e) => { had_err=true; err_msg=Some(e); break; }
                    };
                    let final_res = if complement {
                        for r in &resolved { if r.start==0 { panic!("We didn't use an extract function that counted the number of fields"); } }
                        let mut comp_res=Vec::new();
                        for r in &resolved {
                            if r.start>1 { comp_res.push(Resolved { start:1, end:r.start-1, fallback:None, raw:"".to_string(), is_range:true }); }
                            if r.end < split.fields.len() { comp_res.push(Resolved { start:r.end+1, end:split.fields.len(), fallback:None, raw:"".to_string(), is_range:true }); }
                        }
                        if comp_res.is_empty() { had_err=true; err_msg=Some("Error: the complement is empty".to_string()); break; }
                        comp_res
                    } else { resolved };
                    let mut pieces=Vec::new();
                    for res in &final_res {
                        if res.start==0 {
                            pieces.push(res.fallback.clone().unwrap());
                        } else if res.is_range {
                            pieces.push(build_range_slice(&split, res.start, res.end, &replace_opt));
                        } else {
                            pieces.push(split.fields[res.start-1].clone());
                        }
                    }
                    let ph_str = if join_flag==Some(true) || replace_opt.is_some() {
                        let jd = replace_opt.clone().unwrap_or(if delim_info.is_regex { "".to_string() } else { delim_info.pattern.clone() });
                        pieces.join(&jd)
                    } else {
                        pieces.concat()
                    };
                    ph_exps.push(ph_str);
                }
            }
            if had_err {
                if let Some(em)=err_msg { eprintln!("{}", em); }
                overall_error=true;
                continue;
            }
            let ph_positions: Vec<usize> = fmt_parts.iter().enumerate().filter(|(_,p)| matches!(p, FormatPart::Placeholder(_))).map(|(i,_)| i).collect();
            let mut final_out=String::new();
            let mut ph_idx=0;
            let mut last_was_ph=false;
            for (idx, part) in fmt_parts.iter().enumerate() {
                match part {
                    FormatPart::Lit(l) => {
                        let is_between = {
                            let prev = ph_positions.iter().filter(|&&p| p < idx).last();
                            let next = ph_positions.iter().find(|&&p| p > idx);
                            prev.is_some() && next.is_some()
                        };
                        if join_flag==Some(true) && is_between {
                            let jd = replace_opt.clone().unwrap_or(if delim_info.is_regex { "".to_string() } else { delim_info.pattern.clone() });
                            final_out.push_str(&jd);
                            final_out.push_str(l);
                        } else {
                            final_out.push_str(l);
                        }
                        last_was_ph=false;
                    },
                    FormatPart::Placeholder(_) => {
                        if last_was_ph && join_flag==Some(true) {
                            let jd = replace_opt.clone().unwrap_or(if delim_info.is_regex { "".to_string() } else { delim_info.pattern.clone() });
                            final_out.push_str(&jd);
                        }
                        final_out.push_str(&ph_exps[ph_idx]);
                        ph_idx+=1;
                        last_was_ph=true;
                    }
                }
            }
            if zero_terminated {
                out_handle.write_all(final_out.as_bytes()).unwrap();
                out_handle.write_all(&[0]).unwrap();
            } else {
                out_handle.write_all(final_out.as_bytes()).unwrap();
                out_handle.write_all(b"\n").unwrap();
            }
        } else {
            // plain fields
            let mut out_pieces: Vec<String> = Vec::new();
            let mut had_err=false;
            let mut err_local: Option<String>=None;
            for bitem in &bounds_list {
                match bitem {
                    BoundItem::Single { value, fallback, raw } => {
                        let pos_opt = if *value>0 {
                            if (*value as usize) > split.fields.len() { None } else { Some(*value as usize) }
                        } else {
                            let p = split.fields.len() as i64 + *value +1;
                            if p<1 || p> split.fields.len() as i64 { None } else { Some(p as usize) }
                        };
                        if let Some(p)=pos_opt {
                            out_pieces.push(split.fields[p-1].clone());
                        } else {
                            let fb = fallback.clone().or(fallback_oob_opt.clone());
                            if let Some(fb_str)=fb {
                                out_pieces.push(fb_str);
                            } else {
                                if !out_pieces.is_empty() {
                                    if join_flag==Some(true) || replace_opt.is_some() {
                                        let jd = replace_opt.clone().unwrap_or(if delim_info.is_regex { "".to_string() } else { delim_info.pattern.clone() });
                                        let joined = out_pieces.join(&jd);
                                        let to_print = format!("{}{}", joined, jd);
                                        if zero_terminated {
                                            out_handle.write_all(to_print.as_bytes()).unwrap();
                                            out_handle.write_all(&[0]).unwrap();
                                        } else {
                                            out_handle.write_all(to_print.as_bytes()).unwrap();
                                            out_handle.write_all(b"\n").unwrap();
                                        }
                                    } else {
                                        let conc = out_pieces.concat();
                                        if zero_terminated {
                                            out_handle.write_all(conc.as_bytes()).unwrap();
                                            out_handle.write_all(&[0]).unwrap();
                                        } else {
                                            out_handle.write_all(conc.as_bytes()).unwrap();
                                            out_handle.write_all(b"\n").unwrap();
                                        }
                                    }
                                }
                                err_local=Some(format!("Error: Out of bounds: {}", raw));
                                had_err=true;
                                overall_error=true;
                                break;
                            }
                        }
                    },
                    BoundItem::Range { left, right, fallback, raw } => {
                        let left_val = left.unwrap_or(1);
                        let right_val = right.unwrap_or(split.fields.len() as i64);
                        let left_pos_opt = if left.is_none() { Some(1) } else {
                            let lv=left_val;
                            if lv>0 {
                                if (lv as usize) > split.fields.len() { None } else { Some(lv as usize) }
                            } else {
                                let p = split.fields.len() as i64 + lv +1;
                                if p<1 { None } else { Some(p as usize) }
                            }
                        };
                        let right_pos_opt = if right.is_none() { Some(split.fields.len()) } else {
                            let rv=right_val;
                            if rv>0 {
                                if (rv as usize) > split.fields.len() {
                                    Some(split.fields.len())
                                } else { Some(rv as usize) }
                            } else {
                                let p = split.fields.len() as i64 + rv +1;
                                if p<1 { Some(1) } else { Some(p as usize) }
                            }
                        };
                        if left_pos_opt.is_none() {
                            let fb = fallback.clone().or(fallback_oob_opt.clone());
                            if fb.is_some() {
                                out_pieces.push(fb.unwrap());
                            } else {
                                if !out_pieces.is_empty() {
                                    if join_flag==Some(true) || replace_opt.is_some() {
                                        let jd = replace_opt.clone().unwrap_or(if delim_info.is_regex { "".to_string() } else { delim_info.pattern.clone() });
                                        let joined = out_pieces.join(&jd);
                                        let to_print = format!("{}{}", joined, jd);
                                        if zero_terminated {
                                            out_handle.write_all(to_print.as_bytes()).unwrap();
                                            out_handle.write_all(&[0]).unwrap();
                                        } else {
                                            out_handle.write_all(to_print.as_bytes()).unwrap();
                                            out_handle.write_all(b"\n").unwrap();
                                        }
                                    } else {
                                        let conc = out_pieces.concat();
                                        if zero_terminated {
                                            out_handle.write_all(conc.as_bytes()).unwrap();
                                            out_handle.write_all(&[0]).unwrap();
                                        } else {
                                            out_handle.write_all(conc.as_bytes()).unwrap();
                                            out_handle.write_all(b"\n").unwrap();
                                        }
                                    }
                                }
                                err_local=Some(format!("Error: Out of bounds: {}", left_val));
                                had_err=true;
                                overall_error=true;
                                break;
                            }
                        } else {
                            let lpos = left_pos_opt.unwrap();
                            let rpos = right_pos_opt.unwrap();
                            if lpos > rpos {
                                let fb = fallback.clone().or(fallback_oob_opt.clone());
                                if fb.is_some() {
                                    out_pieces.push(fb.unwrap());
                                } else {
                                    if !out_pieces.is_empty() {
                                        if join_flag==Some(true) || replace_opt.is_some() {
                                            let jd = replace_opt.clone().unwrap_or(if delim_info.is_regex { "".to_string() } else { delim_info.pattern.clone() });
                                            let joined = out_pieces.join(&jd);
                                            let to_print = format!("{}{}", joined, jd);
                                            if zero_terminated {
                                                out_handle.write_all(to_print.as_bytes()).unwrap();
                                                out_handle.write_all(&[0]).unwrap();
                                            } else {
                                                out_handle.write_all(to_print.as_bytes()).unwrap();
                                                out_handle.write_all(b"\n").unwrap();
                                            }
                                        } else {
                                            let conc = out_pieces.concat();
                                            if zero_terminated {
                                                out_handle.write_all(conc.as_bytes()).unwrap();
                                                out_handle.write_all(&[0]).unwrap();
                                            } else {
                                                out_handle.write_all(conc.as_bytes()).unwrap();
                                                out_handle.write_all(b"\n").unwrap();
                                            }
                                        }
                                    }
                                    err_local=Some(format!("Error: Field left value cannot be greater than right value"));
                                    had_err=true;
                                    overall_error=true;
                                    break;
                                }
                            } else {
                                let slice = build_range_slice(&split, lpos, rpos, &replace_opt);
                                out_pieces.push(slice);
                            }
                        }
                    }
                }
            }
            if had_err {
                if let Some(em)=err_local { eprintln!("{}", em); }
                continue;
            }

            // complement handling
            let mut final_pieces: Vec<String> = Vec::new();
            if complement {
                let resolved = match resolve_bounds(split.fields.len(), &bounds_list, &fallback_oob_opt) {
                    Ok(v) => v,
                    Err(_) => { panic!("We didn't use an extract function that counted the number of fields"); }
                };
                for r in &resolved { if r.start==0 { panic!("We didn't use an extract function that counted the number of fields"); } }
                let mut comp_resolved: Vec<Resolved> = Vec::new();
                for r in resolved {
                    if r.start>1 { comp_resolved.push(Resolved { start:1, end:r.start-1, fallback:None, raw:"".to_string(), is_range:true }); }
                    if r.end < split.fields.len() { comp_resolved.push(Resolved { start:r.end+1, end:split.fields.len(), fallback:None, raw:"".to_string(), is_range:true }); }
                }
                if comp_resolved.is_empty() {
                    eprintln!("Error: the complement is empty");
                    overall_error=true;
                    continue;
                }
                for res in &comp_resolved {
                    if res.is_range {
                        final_pieces.push(build_range_slice(&split, res.start, res.end, &replace_opt));
                    } else {
                        final_pieces.push(split.fields[res.start-1].clone());
                    }
                }
            } else {
                final_pieces = out_pieces;
            }

            if json {
                // json flatten
                let resolved_for_json = match resolve_bounds(split.fields.len(), &bounds_list, &fallback_oob_opt) {
                    Ok(v) => v,
                    Err(e) => {
                        eprintln!("{}", e);
                        overall_error=true;
                        continue;
                    }
                };
                let mut elems: Vec<String> = Vec::new();
                let final_res_for_json = if complement {
                    let mut sel_set = HashSet::new();
                    for r in &resolved_for_json { for p in r.start..=r.end { sel_set.insert(p); } }
                    let mut comp_res = Vec::new();
                    for idx in 1..=split.fields.len() { if !sel_set.contains(&idx) { comp_res.push(Resolved { start:idx, end:idx, fallback:None, raw:"".to_string(), is_range:false }); } }
                    comp_res
                } else { resolved_for_json };
                for res in &final_res_for_json {
                    if res.start==0 {
                        elems.push(res.fallback.clone().unwrap());
                    } else if res.is_range {
                        for p in res.start..=res.end { elems.push(split.fields[p-1].clone()); }
                    } else {
                        elems.push(split.fields[res.start-1].clone());
                    }
                }
                let json_str = format!("[{}]", elems.iter().map(|e| format!("\"{}\"", json_escape(e))).collect::<Vec<_>>().join(","));
                if zero_terminated {
                    out_handle.write_all(json_str.as_bytes()).unwrap();
                    out_handle.write_all(&[0]).unwrap();
                } else {
                    out_handle.write_all(json_str.as_bytes()).unwrap();
                    out_handle.write_all(b"\n").unwrap();
                }
            } else {
                let final_line = if join_flag==Some(true) || replace_opt.is_some() {
                    let jd = replace_opt.clone().unwrap_or(if delim_info.is_regex { "".to_string() } else { delim_info.pattern.clone() });
                    final_pieces.join(&jd)
                } else {
                    final_pieces.concat()
                };
                // empty field handling: if final_line empty but we had valid selection (e.g., empty field), output newline
                if !final_line.is_empty() || !final_pieces.is_empty() {
                    if zero_terminated {
                        out_handle.write_all(final_line.as_bytes()).unwrap();
                        out_handle.write_all(&[0]).unwrap();
                    } else {
                        out_handle.write_all(final_line.as_bytes()).unwrap();
                        out_handle.write_all(b"\n").unwrap();
                    }
                } else {
                    // check if we had any resolved (for empty field)
                    // If split.fields contains empty and we selected it, final_pieces would contain "".
                    // In that case final_pieces not empty (contains ""), so previous branch would have !final_pieces.is_empty true, and we output final_line (empty) + newline, which is correct.
                    // So this branch is for when no pieces? Then nothing? Actually for empty input line, we already continued if only_delimited.
                    // For empty field, final_pieces = [""] => !empty true, final_line "" => we output newline via previous branch.
                    // So this else is unreachable, but we still output nothing?
                    if !final_pieces.is_empty() {
                        if zero_terminated {
                            out_handle.write_all(&[0]).unwrap();
                        } else {
                            out_handle.write_all(b"\n").unwrap();
                        }
                    }
                }
            }
        }
    }

    if overall_error { process::exit(1); }
}
